"""Bounded, read-only IDB-wide collection for whole-binary triage.

Everything here runs once, on an explicit analyst action (never at plugin
startup or while idle), reads IDA data through injected modules, and returns
immutable, size-limited summaries. Nothing in this module writes to the IDB.
Missing optional IDA facilities yield partial data instead of an error.
"""

from __future__ import annotations

import bisect
import importlib
from dataclasses import dataclass
from types import ModuleType
from typing import Dict, FrozenSet, List, Optional, Set, Tuple

from ida_ai_malware_analyst_plugin.ida.compatibility import IdaModules, load_ida_modules


@dataclass(frozen=True)
class TriageLimits:
    """Hard bounds that keep one triage pass compact even on very large IDBs."""

    max_functions: int = 5000
    max_imports: int = 2000
    max_strings: int = 3000
    max_segments: int = 64
    min_string_length: int = 5
    max_entry_points: int = 256
    max_instructions_per_function: int = 2000
    max_callees_per_function: int = 32
    max_strings_per_function: int = 16
    max_xrefs_counted: int = 1000

    def __post_init__(self) -> None:
        for field_name, value in self.__dict__.items():
            if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
                raise ValueError("{0} must be a positive integer".format(field_name))


@dataclass(frozen=True)
class TriageModules:
    """Optional IDA modules used only by triage (kept out of ``IdaModules``)."""

    segment: Optional[ModuleType] = None
    entry: Optional[ModuleType] = None
    ida: Optional[ModuleType] = None


def _optional_module(name: str) -> Optional[ModuleType]:
    try:
        return importlib.import_module(name)
    except ImportError:
        return None


def load_triage_modules() -> TriageModules:
    return TriageModules(
        segment=_optional_module("ida_segment"),
        entry=_optional_module("ida_entry"),
        ida=_optional_module("ida_ida"),
    )


@dataclass(frozen=True)
class SegmentInfo:
    name: str
    start: int
    end: int
    executable: bool
    writable: bool
    readable: bool
    segment_class: Optional[str] = None

    @property
    def size(self) -> int:
        return max(0, self.end - self.start)

    @property
    def executable_and_writable(self) -> bool:
        return self.executable and self.writable


@dataclass(frozen=True)
class ImportInfo:
    dll: str
    name: str
    address: int


@dataclass(frozen=True)
class StringInfo:
    address: int
    value: str


@dataclass(frozen=True)
class EntryPoint:
    address: int
    name: str
    ordinal: int


@dataclass(frozen=True)
class FunctionSummary:
    """Compact per-function facts; never assembly or pseudocode."""

    address: int
    name: str
    size: int
    instruction_count: int
    xrefs_to: int
    callee_count: int
    imports_called: Tuple[str, ...]
    string_count: int
    referenced_strings: Tuple[str, ...] = ()
    callees: Tuple[int, ...] = ()
    segment_name: Optional[str] = None
    in_executable_writable_segment: bool = False
    is_thunk: bool = False
    is_library: bool = False
    is_entry_point: bool = False
    truncated: bool = False


@dataclass(frozen=True)
class BinaryOverview:
    architecture: Optional[str]
    bitness: Optional[int]
    file_type: Optional[str]
    entry_points: Tuple[EntryPoint, ...]
    segments: Tuple[SegmentInfo, ...]
    imports: Tuple[ImportInfo, ...]
    functions: Tuple[FunctionSummary, ...]
    strings: Tuple[StringInfo, ...]
    has_tls_callbacks: Optional[bool] = None
    resources_present: Optional[bool] = None
    truncated_sections: Tuple[str, ...] = ()
    unavailable_sections: Tuple[str, ...] = ()


_IDA_ERRORS = (AttributeError, RuntimeError, TypeError, ValueError, OverflowError)
_FUNC_THUNK = 0x80
_FUNC_LIB = 0x4
_SEGPERM_EXEC = 1
_SEGPERM_WRITE = 2
_SEGPERM_READ = 4


def collect_binary_overview(
    modules: Optional[IdaModules] = None,
    limits: TriageLimits = TriageLimits(),
    triage_modules: Optional[TriageModules] = None,
) -> Optional[BinaryOverview]:
    """Collect a bounded IDB-wide overview; ``None`` only when IDA is unavailable."""
    loaded = modules or load_ida_modules()
    if not loaded.available:
        return None
    extra = triage_modules or load_triage_modules()
    truncated: List[str] = []
    unavailable: List[str] = []

    architecture, bitness = _architecture(loaded, extra)
    if architecture is None:
        unavailable.append("architecture")
    file_type = _file_type(loaded)
    if file_type is None:
        unavailable.append("file_type")

    entry_points, entries_truncated, entries_ok = _entry_points(loaded, extra, limits.max_entry_points)
    _note(truncated, unavailable, "entry_points", entries_truncated, entries_ok)
    segments, segments_truncated, segments_ok = _segments(loaded, extra, limits.max_segments)
    _note(truncated, unavailable, "segments", segments_truncated, segments_ok)
    imports, imports_truncated, imports_ok = _imports(loaded, limits.max_imports)
    _note(truncated, unavailable, "imports", imports_truncated, imports_ok)
    strings, strings_truncated, strings_ok = _strings(loaded, limits)
    _note(truncated, unavailable, "strings", strings_truncated, strings_ok)

    import_names: Dict[int, str] = {item.address: item.name for item in imports}
    string_values: Dict[int, str] = {item.address: item.value for item in strings}
    entry_addresses = frozenset(item.address for item in entry_points)
    segment_index = _SegmentIndex(segments)

    functions, functions_truncated, functions_ok = _functions(
        loaded, limits, import_names, string_values, entry_addresses, segment_index
    )
    _note(truncated, unavailable, "functions", functions_truncated, functions_ok)

    return BinaryOverview(
        architecture=architecture,
        bitness=bitness,
        file_type=file_type,
        entry_points=entry_points,
        segments=segments,
        imports=imports,
        functions=functions,
        strings=strings,
        has_tls_callbacks=_tls_hint(loaded, entry_points),
        resources_present=_resources_hint(segments) if segments_ok else None,
        truncated_sections=tuple(truncated),
        unavailable_sections=tuple(unavailable),
    )


def function_summary(
    address: int,
    modules: Optional[IdaModules] = None,
    limits: TriageLimits = TriageLimits(),
    import_addresses: Optional[Dict[int, str]] = None,
    string_addresses: Optional[Dict[int, str]] = None,
    entry_addresses: FrozenSet[int] = frozenset(),
    segments: Tuple[SegmentInfo, ...] = (),
) -> Optional[FunctionSummary]:
    """Summarize a single function; import/string maps are optional accelerators.

    Without a precomputed import map, import targets are recognized as named,
    non-function XREF targets whose names IDA marks as imports (``__imp_`` prefix)
    or that live in the IDB's import table lookup when available.
    """
    if not isinstance(address, int) or isinstance(address, bool) or address < 0:
        raise ValueError("Function address must be a non-negative integer")
    loaded = modules or load_ida_modules()
    if not loaded.available:
        return None
    try:
        function = loaded.funcs.get_func(address)
    except _IDA_ERRORS:
        return None
    if function is None:
        return None
    imports = import_addresses if import_addresses is not None else _import_map(loaded, limits.max_imports)
    strings = string_addresses if string_addresses is not None else {}
    return _summarize(function, loaded, limits, imports, strings, entry_addresses, _SegmentIndex(segments))


# ---------------------------------------------------------------------------
# Collection helpers
# ---------------------------------------------------------------------------


def _note(truncated: List[str], unavailable: List[str], name: str, was_truncated: bool, ok: bool) -> None:
    if not ok:
        unavailable.append(name)
    elif was_truncated:
        truncated.append(name)


def _architecture(modules: IdaModules, extra: TriageModules) -> Tuple[Optional[str], Optional[int]]:
    architecture: Optional[str] = None
    bitness: Optional[int] = None
    if extra.ida is not None:
        try:
            procname = extra.ida.inf_get_procname()
            architecture = str(procname) if procname else None
        except _IDA_ERRORS:
            architecture = None
        try:
            if extra.ida.inf_is_64bit():
                bitness = 64
            elif callable(getattr(extra.ida, "inf_is_32bit_exactly", None)):
                bitness = 32 if extra.ida.inf_is_32bit_exactly() else 16
            elif callable(getattr(extra.ida, "inf_is_32bit", None)):
                bitness = 32 if extra.ida.inf_is_32bit() else 16
        except _IDA_ERRORS:
            bitness = None
    if architecture is None or bitness is None:
        getter = getattr(modules.idaapi, "get_inf_structure", None)
        if callable(getter):
            try:
                info = getter()
                if architecture is None:
                    procname = getattr(info, "procname", None) or getattr(info, "procName", None)
                    architecture = str(procname) if procname else None
                if bitness is None:
                    if info.is_64bit():
                        bitness = 64
                    elif info.is_32bit():
                        bitness = 32
                    else:
                        bitness = 16
            except _IDA_ERRORS:
                pass
    return architecture, bitness


def _file_type(modules: IdaModules) -> Optional[str]:
    getter = getattr(modules.idaapi, "get_file_type_name", None)
    if not callable(getter):
        return None
    try:
        value = getter()
    except _IDA_ERRORS:
        return None
    return str(value) if value else None


def _entry_points(
    modules: IdaModules, extra: TriageModules, maximum: int
) -> Tuple[Tuple[EntryPoint, ...], bool, bool]:
    if extra.entry is None:
        return (), False, False
    output: List[EntryPoint] = []
    truncated = False
    try:
        count = int(extra.entry.get_entry_qty())
        for index in range(count):
            if len(output) >= maximum:
                truncated = True
                break
            ordinal = extra.entry.get_entry_ordinal(index)
            address = extra.entry.get_entry(ordinal)
            if address is None or address == getattr(modules.idaapi, "BADADDR", None):
                continue
            name = extra.entry.get_entry_name(ordinal) or modules.name.get_name(address) or "entry_{0:X}".format(address)
            output.append(EntryPoint(address=int(address), name=str(name), ordinal=int(ordinal)))
    except _IDA_ERRORS:
        return tuple(output), truncated, bool(output)
    return tuple(output), truncated, True


def _segments(
    modules: IdaModules, extra: TriageModules, maximum: int
) -> Tuple[Tuple[SegmentInfo, ...], bool, bool]:
    if extra.segment is None:
        return (), False, False
    output: List[SegmentInfo] = []
    truncated = False
    try:
        segments = list(_iterate_segments(modules, extra))
        for segment in segments:
            if segment is None:
                continue
            if len(output) >= maximum:
                truncated = True
                break
            perm = int(getattr(segment, "perm", 0) or 0)
            name = extra.segment.get_segm_name(segment) or "seg_{0:X}".format(segment.start_ea)
            segment_class: Optional[str] = None
            class_getter = getattr(extra.segment, "get_segm_class", None)
            if callable(class_getter):
                try:
                    segment_class = class_getter(segment) or None
                except _IDA_ERRORS:
                    segment_class = None
            executable = bool(perm & getattr(extra.segment, "SEGPERM_EXEC", _SEGPERM_EXEC))
            if not perm and segment_class == "CODE":
                executable = True
            output.append(
                SegmentInfo(
                    name=str(name),
                    start=int(segment.start_ea),
                    end=int(segment.end_ea),
                    executable=executable,
                    writable=bool(perm & getattr(extra.segment, "SEGPERM_WRITE", _SEGPERM_WRITE)),
                    readable=bool(perm & getattr(extra.segment, "SEGPERM_READ", _SEGPERM_READ)),
                    segment_class=str(segment_class) if segment_class else None,
                )
            )
    except _IDA_ERRORS:
        return tuple(output), truncated, bool(output)
    output.sort(key=lambda item: item.start)
    return tuple(output), truncated, True


def _iterate_segments(modules: IdaModules, extra: TriageModules):
    if modules.idautils is not None and callable(getattr(modules.idautils, "Segments", None)):
        for start in modules.idautils.Segments():
            yield extra.segment.getseg(start)
        return
    count = int(extra.segment.get_segm_qty())
    for index in range(count):
        yield extra.segment.getnseg(index)


def _imports(modules: IdaModules, maximum: int) -> Tuple[Tuple[ImportInfo, ...], bool, bool]:
    nalt = modules.nalt
    if nalt is None or not callable(getattr(nalt, "get_import_module_qty", None)):
        return (), False, False
    output: List[ImportInfo] = []
    truncated = [False]
    try:
        count = int(nalt.get_import_module_qty())
        for index in range(count):
            if truncated[0]:
                break
            dll = nalt.get_import_module_name(index) or "module_{0}".format(index)

            def visitor(address, name, ordinal, _dll=dll):
                if len(output) >= maximum:
                    truncated[0] = True
                    return False
                label = name if name else "ordinal_{0}".format(ordinal)
                output.append(ImportInfo(dll=str(_dll), name=str(label), address=int(address)))
                return True

            nalt.enum_import_names(index, visitor)
    except _IDA_ERRORS:
        return tuple(output), truncated[0], bool(output)
    return tuple(output), truncated[0], True


def _import_map(modules: IdaModules, maximum: int) -> Dict[int, str]:
    imports, _, _ = _imports(modules, maximum)
    return {item.address: item.name for item in imports}


def _strings(modules: IdaModules, limits: TriageLimits) -> Tuple[Tuple[StringInfo, ...], bool, bool]:
    if modules.idautils is None or not callable(getattr(modules.idautils, "Strings", None)):
        return (), False, False
    output: List[StringInfo] = []
    truncated = False
    try:
        table = modules.idautils.Strings()
        for item in table:
            if item is None:
                continue
            value = str(item)
            if len(value) < limits.min_string_length:
                continue
            if len(output) >= limits.max_strings:
                truncated = True
                break
            output.append(StringInfo(address=int(item.ea), value=value))
    except _IDA_ERRORS:
        return tuple(output), truncated, bool(output)
    return tuple(output), truncated, True


class _SegmentIndex:
    """Sorted segment lookup so every function resolves its segment in O(log n)."""

    def __init__(self, segments: Tuple[SegmentInfo, ...]) -> None:
        ordered = sorted(segments, key=lambda item: item.start)
        self._starts = [item.start for item in ordered]
        self._segments = ordered

    def find(self, address: int) -> Optional[SegmentInfo]:
        index = bisect.bisect_right(self._starts, address) - 1
        if index < 0:
            return None
        segment = self._segments[index]
        return segment if segment.start <= address < segment.end else None


def _functions(
    modules: IdaModules,
    limits: TriageLimits,
    imports: Dict[int, str],
    strings: Dict[int, str],
    entry_addresses: FrozenSet[int],
    segment_index: _SegmentIndex,
) -> Tuple[Tuple[FunctionSummary, ...], bool, bool]:
    if modules.idautils is None or not callable(getattr(modules.idautils, "Functions", None)):
        return (), False, False
    output: List[FunctionSummary] = []
    truncated = False
    try:
        for start in modules.idautils.Functions():
            if len(output) >= limits.max_functions:
                truncated = True
                break
            function = modules.funcs.get_func(start)
            if function is None:
                continue
            summary = _summarize(function, modules, limits, imports, strings, entry_addresses, segment_index)
            if summary is not None:
                output.append(summary)
    except _IDA_ERRORS:
        return tuple(output), truncated, bool(output)
    return tuple(output), truncated, True


def _summarize(
    function,
    modules: IdaModules,
    limits: TriageLimits,
    imports: Dict[int, str],
    strings: Dict[int, str],
    entry_addresses: FrozenSet[int],
    segment_index: _SegmentIndex,
) -> Optional[FunctionSummary]:
    try:
        start = int(function.start_ea)
        end = int(function.end_ea)
    except _IDA_ERRORS:
        return None
    name = _safe_name(modules, start)
    flags = int(getattr(function, "flags", 0) or 0)
    funcs = modules.funcs
    is_thunk = bool(flags & getattr(funcs, "FUNC_THUNK", _FUNC_THUNK))
    is_library = bool(flags & getattr(funcs, "FUNC_LIB", _FUNC_LIB))

    instruction_count = 0
    callees: List[int] = []
    callee_seen: Set[int] = set()
    import_names: List[str] = []
    import_seen: Set[str] = set()
    referenced: List[str] = []
    string_count = 0
    string_seen: Set[int] = set()
    truncated = False

    idautils = modules.idautils
    if idautils is not None and callable(getattr(idautils, "FuncItems", None)):
        try:
            for item in idautils.FuncItems(start):
                if instruction_count >= limits.max_instructions_per_function:
                    truncated = True
                    break
                instruction_count += 1
                for xref in idautils.XrefsFrom(item, 0):
                    target = int(xref.to)
                    if target in imports:
                        label = imports[target]
                        if label not in import_seen:
                            import_seen.add(label)
                            import_names.append(label)
                        continue
                    if target in strings:
                        if target not in string_seen:
                            string_seen.add(target)
                            string_count += 1
                            if len(referenced) < limits.max_strings_per_function:
                                referenced.append(strings[target])
                        continue
                    if start <= target < end:
                        continue
                    callee = funcs.get_func(target)
                    if callee is None:
                        continue
                    callee_start = int(callee.start_ea)
                    if callee_start == start or callee_start in callee_seen:
                        continue
                    callee_seen.add(callee_start)
                    if len(callees) < limits.max_callees_per_function:
                        callees.append(callee_start)
                    else:
                        truncated = True
        except _IDA_ERRORS:
            truncated = True
    else:
        instruction_count = max(0, end - start)

    segment = segment_index.find(start)
    return FunctionSummary(
        address=start,
        name=name,
        size=max(0, end - start),
        instruction_count=instruction_count,
        xrefs_to=_xref_count(modules, start, limits.max_xrefs_counted),
        callee_count=len(callee_seen),
        imports_called=tuple(import_names),
        string_count=string_count,
        referenced_strings=tuple(referenced),
        callees=tuple(callees),
        segment_name=segment.name if segment else None,
        in_executable_writable_segment=bool(segment and segment.executable_and_writable),
        is_thunk=is_thunk,
        is_library=is_library,
        is_entry_point=start in entry_addresses,
        truncated=truncated,
    )


def _safe_name(modules: IdaModules, address: int) -> str:
    try:
        return modules.name.get_name(address) or "sub_{0:X}".format(address)
    except _IDA_ERRORS:
        return "sub_{0:X}".format(address)


def _xref_count(modules: IdaModules, address: int, maximum: int) -> int:
    if modules.idautils is None or not callable(getattr(modules.idautils, "XrefsTo", None)):
        return 0
    count = 0
    try:
        for _ in modules.idautils.XrefsTo(address, 0):
            count += 1
            if count >= maximum:
                break
    except _IDA_ERRORS:
        pass
    return count


def _tls_hint(modules: IdaModules, entry_points: Tuple[EntryPoint, ...]) -> Optional[bool]:
    if any("tls" in item.name.lower() for item in entry_points):
        return True
    lookup = getattr(modules.name, "get_name_ea", None)
