def entry_functions(overview: BinaryOverview) -> Tuple[int, ...]:
    """Entry points plus well-known entry names, in address order."""
    entries: Set[int] = set()
    known = {item.address for item in overview.functions}
    for item in overview.entry_points:
        if item.address in known:
            entries.add(item.address)
    for item in overview.functions:
        if item.is_entry_point:
            entries.add(item.address)
        canonical = _canonical_entry_name(item.name)
        if canonical in ENTRY_NAMES or canonical.lstrip("_") in ENTRY_NAMES:
            entries.add(item.address)
    return tuple(sorted(entries))


