    {bh.CREDENTIAL_THEFT, bh.RANSOMWARE, bh.HACKTOOL, bh.CRYPTO_MINING, bh.KEYLOGGING, bh.REMOTE_CONTROL, bh.INJECTION, bh.PRIVILEGE}
)
PUP_MIN_SCORE = 40
PUP_MAX_SCORE = 59
_MIN_NAME_FUNCTIONS_ALONE = 3  # distinct author functions whose names alone corroborate a behaviour


def _behaviour_evidence(
    overview: BinaryOverview, scored_categories: Set[str], evidence: List[VerdictEvidence]
) -> Tuple[Set[str], Set[str]]:
    """Score behaviours seen in author names, strings and linked libraries.

    A category is scored once, and only when corroborated: a strong library
    (C2 framework, syscall/evasion kit), two independent string groups, a name
    hit plus a string/library/API hit, or several distinct author functions
    whose names agree. Returns the scored categories and the evidence kinds
    that contributed (``names``, ``strings``, ``libraries``, ``apis``).
    """
    index = getattr(overview, "origin_index", None)

    def is_author(item: object) -> bool:
        return getattr(item, "origin", "unknown") in ANALYSABLE_ORIGINS and not getattr(item, "is_thunk", False)

    names = bh.group_name_hits(bh.author_name_hits(overview.functions, is_author))
    string_hits: Dict[str, List[bh.StringHit]] = {}
    for hit in bh.classify_strings((item.address, item.value) for item in overview.strings):
        string_hits.setdefault(hit.category, []).append(hit)
    library_hits: Dict[str, List[bh.LibraryHit]] = {}
    if index is not None:
        for hit in bh.classify_libraries(index.third_party_libraries):
            library_hits.setdefault(hit.category, []).append(hit)

    scored: Set[str] = set()
    sources: Set[str] = set()
    for category in sorted(set(names) | set(string_hits) | set(library_hits)):
        weight_key = "behaviour_" + category
        if weight_key not in WEIGHTS:
            continue
        api_category = _BEHAVIOUR_TO_API_CATEGORY.get(category)
        api_hit = api_category in scored_categories if api_category else False
        name_list = names.get(category, [])
        strings_list = string_hits.get(category, [])
        groups = {hit.group for hit in strings_list}
        libs = library_hits.get(category, [])
        strong_lib = any(hit.strong for hit in libs)
        corroborated = (
            strong_lib
            or len(groups) >= 2
            or (name_list and (strings_list or libs or api_hit))
            or len({hit.address for hit in name_list}) >= _MIN_NAME_FUNCTIONS_ALONE
            or (category in (bh.RANSOMWARE, bh.HACKTOOL, bh.CRYPTO_MINING) and len(strings_list) >= 2)
            or (category == bh.CREDENTIAL_THEFT and len(strings_list) >= 3)
        )
        if not corroborated:
            continue
        if api_hit and category in ("injection", "persistence"):
            # The IAT rule already scored this capability; keep one weight per capability.
            continue
        parts: List[str] = []
        addresses: List[str] = []
        if name_list:
            sources.add("names")
            shown = ", ".join(hit.name for hit in name_list[:4])
            parts.append("author functions {0}{1}".format(shown, " (+{0})".format(len(name_list) - 4) if len(name_list) > 4 else ""))
            addresses.extend(_hex(hit.address) for hit in name_list[:_MAX_ADDRESSES])
        if strings_list:
            sources.add("strings")
            parts.append("strings ({0}): {1}".format(
                ", ".join(sorted(groups)), "; ".join('"{0}"'.format(hit.text[:50]) for hit in strings_list[:2])
            ))
            addresses.extend(_hex(hit.address) for hit in strings_list[:2] if hit.address >= 0)
        if libs:
            sources.add("libraries")
            parts.append("libraries: " + ", ".join("{0} [{1}]".format(hit.library, hit.label) for hit in libs[:3]))
        if api_hit:
            sources.add("apis")
        scored.add(category)
        evidence.append(
            VerdictEvidence(
                category="behaviour:" + category,
                weight=WEIGHTS[weight_key],
                description="{0}: {1}".format(bh.CATEGORY_LABELS.get(category, category), " | ".join(parts)),
                addresses=tuple(dict.fromkeys(addresses))[:_MAX_ADDRESSES],
                basis="observed" if (strings_list or libs) else "inferred",
            )
        )
    return scored, sources


def _classify(
    score: int,
    band: VerdictBand,
    categories: Set[str],
    sources: Set[str],
    packing: Sequence[str],
    pup_only: bool,
    index: Any,
    language: str,
    named_author: int,
) -> Tuple[str, str, int]:
    """Final label, subtype and a confidence that reflects how many independent sources agree."""
    kinds = set(sources)
    if categories & {"injection", "dynamic_resolution", "anti_debug", "persistence", "network", "crypto", "anti_analysis"}:
        kinds.add("apis")
    if packing:
        kinds.add("packing")
    if band in (VerdictBand.MALICIOUS, VerdictBand.LIKELY_MALICIOUS):
        subtype = _malware_subtype(categories)
        confidence = 60 + int((score - 60) * 0.8) + 6 * max(0, len(kinds) - 1)
        if named_author == 0 and language in STATIC_RUNTIME_LANGUAGES:
            confidence -= 10
        return "MALWARE", subtype, max(55, min(97, confidence))
    if pup_only or (band == VerdictBand.SUSPICIOUS_PUP and categories & bh.PUP_CATEGORIES):
        subtype = "Browser hijacker" if bh.PUP_BROWSER_HIJACK in categories else "Adware / bundler"
        return "PUP/PUA", subtype, min(90, 65 + 6 * len(kinds))
    if band == VerdictBand.SUSPICIOUS_PUP:
        return "SUSPICIOUS-INCONCLUSIVE", _malware_subtype(categories) if categories else "", 50
    confidence = 60 + (19 - min(score, 19)) + (10 if index is not None and index.author_count else 0)
    if packing:
        confidence -= 15
    if index is not None and language in STATIC_RUNTIME_LANGUAGES and named_author == 0:
        confidence -= 15
    if band == VerdictBand.LIKELY_LEGITIMATE:
        confidence -= 10
    return "LEGITIMATE", "", max(40, min(90, confidence))


def _malware_subtype(categories: Set[str]) -> str:
    c = categories
    if bh.HACKTOOL in c:
        return "Hacktool / C2 implant" if (bh.C2 in c or "network" in c) else "Hacktool"
    if bh.RANSOMWARE in c:
        return "Ransomware"
    if bh.CREDENTIAL_THEFT in c and c & {bh.REMOTE_CONTROL, bh.SURVEILLANCE, bh.KEYLOGGING}:
        return "Infostealer + RAT"
    if bh.CREDENTIAL_THEFT in c:
        return "Infostealer"
    if bh.CRYPTO_MINING in c:
        return "Coin miner"
    if c & {bh.REMOTE_CONTROL, bh.SURVEILLANCE} and (c & {bh.C2, "network"}):
        return "RAT / Backdoor"
    if bh.KEYLOGGING in c:
        return "Keylogger / Spyware"
    if c & {bh.INJECTION, "injection", bh.DOWNLOAD_EXECUTE}:
        return "Loader / Dropper"
    if c & {bh.C2, "network"} and c & {bh.PERSISTENCE, "persistence"}:
        return "Backdoor / Downloader"
    return "Generic malicious"

