# Weight of a capability category when choosing which functions to investigate.
_SELECTION_CATEGORY_WEIGHTS: Dict[str, int] = {
    # behaviour categories from author names (analysis/behaviour)
    "credential_theft": 14, "ransomware": 14, "hacktool": 14, "injection": 12, "remote_control": 11, "keylogging": 10,
    "surveillance": 9, "c2": 9, "privilege": 8, "crypto_mining": 10, "download_execute": 8, "persistence": 8, "evasion": 7,
    "pup_browser_hijack": 8, "pup_adware": 5, "config_decoding": 6,
    # import-table categories (analysis/triage)
    "dynamic_resolution": 6, "anti_debug": 6, "crypto": 6, "network": 7, "process": 5, "memory": 3, "discovery": 2, "file": 1,
}


def _select_high_value(
    candidates: Sequence[Tuple[int, Optional[int], int]],
    scores: Mapping[int, FunctionScore],
    on_flow: Set[int],
    high_flow: Set[int],
    max_functions: int,
) -> Set[int]:
    """Greedy capability coverage: pick the functions that add the most new capability first."""
    pool = [address for address, _parent, _depth in candidates]
    if len(pool) <= max_functions:
        return set(pool)
    covered: Dict[str, int] = {}
    selected: List[int] = []
    remaining = list(dict.fromkeys(pool))
    while remaining and len(selected) < max_functions:
        best = None
        best_value = None
        for address in remaining:
            score = scores.get(address)
            categories = tuple(score.categories) if score is not None else ()
            gain = 0
            for category in categories:
                weight = _SELECTION_CATEGORY_WEIGHTS.get(category, 3)
                # first function for a category earns full weight, later ones a fraction
                gain += weight if category not in covered else weight // (2 + covered[category])
            local = score.score if score is not None else 0
            value = (gain * 3 + local + (4 if address in high_flow else 0) + (2 if address in on_flow else 0), local, -address)
            if best_value is None or value > best_value:
                best, best_value = address, value
        if best is None:
            break
        selected.append(best)
        remaining.remove(best)
        score = scores.get(best)
        for category in (score.categories if score is not None else ()):
            covered[category] = covered.get(category, 0) + 1
    return set(selected)


