    """Render validated findings only; no model text is executed or interpreted as UI code."""
    def section(title: str, items: tuple[str, ...]) -> str:
        return title + "\n" + ("\n".join("- " + item for item in items) if items else "- None")

    suggested_name = analysis.suggested_name or "None"
    return "\n\n".join((
        "AI Summary\n" + analysis.summary,
        section("Observed Behavior", analysis.observed_behavior),
        section("Evidence", analysis.evidence),
        "Confidence\n" + analysis.confidence_label,
        "Suggested Name\n" + suggested_name,
        section("Uncertainties", analysis.uncertainties),
    ))


def format_naming_result(result: NamingResult) -> str:
    """Plain-text view of accepted name suggestions; every one is only a pending proposal."""
    lines = ["Name Suggestions (pending analyst approval)"]
    if not result.suggestions:
        lines.append("- None accepted")
    for suggestion in result.suggestions:
        target = "0x{0:X}".format(suggestion.address)
        if suggestion.kind == "variable":
            target += " local"
        reason = " — " + suggestion.reason if suggestion.reason else ""
        lines.append(
            "- {0} {1}: {2} → {3} [{4}]{5}".format(
                suggestion.kind, target, suggestion.current_name, suggestion.suggested_name, suggestion.confidence_label, reason
            )
        )
    lines.append("")
    lines.append("Uncertainties")
    if result.uncertainties:
        lines.extend("- " + item for item in result.uncertainties)
    else:
        lines.append("- None")
    return "\n".join(lines)


def format_ask_exchange(question: str, answer: str) -> str:
    """One Ask AI exchange as it is appended to the Ask AI tab."""
    return "Q: {0}\nA: {1}".format(" ".join(question.split()), answer.strip())


def format_investigation_findings(result: InvestigationResult) -> str:
    """Findings-tab text for a synthesised investigation: the root analysis plus the synthesis summary."""
    parts = []
    if result.analysis is not None:
        parts.append(format_analysis_findings(result.analysis))
    parts.append("Investigation Summary\n" + result.summary)
    parts.append(
        "Chain steps: {0}   Path steps: {1}   Indicators: {2}   Functions visited: {3}".format(
            len(result.chain), len(result.analysis_path), len(result.indicators), len(result.visited)
        )
    )
    return "\n\n".join(parts)


def format_result(kind: str, result: Any) -> str:
    """Dispatch to the analysis modules' formatters by action kind."""
    if kind in ("analyze", "investigate") and isinstance(result, FunctionAnalysis):
        return format_analysis_findings(result)
    if kind == "investigate" and isinstance(result, InvestigationResult):
        return format_investigation_findings(result)
    if kind == "sweep" and isinstance(result, SweepReport):
        return format_sweep_summary(result.summary) + "\n\n" + format_attack_chain(result.investigation)
    if kind == "suggest_name" and isinstance(result, NamingResult):
        return format_naming_result(result)
    if kind == "suggest_binary_names" and hasattr(result, "functions_planned"):
        naming = getattr(result, "result", None)
        suggestions = tuple(getattr(naming, "function", ()) or ())
        lines = ["Binary function naming pass", "Functions processed: {0}/{1}".format(result.functions_processed, result.functions_planned),
                 "Batches: {0}".format(result.batches), "Proposals queued for approval: {0}".format(result.proposals_queued)]
        if result.budget_limited:
            lines.append("Coverage limited by the configured token budget.")
        if result.inventory_truncated:
            lines.append("IDA's bounded function inventory was truncated; some binary functions were not included.")
        lines.extend(["", format_naming_result(naming) if isinstance(naming, NamingResult) else "No accepted name suggestions."])
        return "\n".join(lines)
    if kind == "capabilities" and isinstance(result, CapabilityReport):
        return format_capability_report(result)
    if kind == "obfuscation" and isinstance(result, ObfuscationReport):
        return format_obfuscation_report(result)
    if kind == "analyze_binary" and isinstance(result, BinaryTriageOutcome):
        return format_binary_triage(result)
    if kind == "analyze_binary" and isinstance(result, TriageReport):
        return format_triage_report(result)
    if kind == "report":
        return str(getattr(result, "markdown", result))
    return str(result)


def format_artifact_row(artifact: Any) -> str:
    """One Obfuscation-tab list row: ``recipe/helper [status] → preview``."""
    preview = getattr(artifact, "printable_preview", None) or getattr(artifact, "hex_preview", None) or getattr(artifact, "detail", "")
    target = getattr(artifact, "target_address", None)
    where = " @ 0x{0:X}".format(target) if isinstance(target, int) and not isinstance(target, bool) else ""
    return "{0} [{1}]{2} → {3}".format(getattr(artifact, "helper", "?"), getattr(artifact, "status", "?"), where, _display_value(preview))

    try:
        if self._actions.is_running():
            self._set_status("An action is still running. Your question is ready to send when it finishes.")
            return
    except Exception:
        pass
    question = self._question.text().strip()
    if not question:
        self._set_status("Enter a question first")
        return
    self._pending_question = question
    self._question.clear()
    if self._ask_log is not None:
        self._ask_log.clear()
    self.run_kind("ask", question=question)

def _show_result(self, kind: str, result: Any) -> None:
    text = format_result(kind, result)
    if kind == "ask":
        exchange = format_ask_exchange(self._pending_question, text)
        log = getattr(self, "_ask_log", None)
        if log is not None:
            log.appendPlainText(("\n" if log.toPlainText() else "") + exchange)
            scrollbar = log.verticalScrollBar()
            if scrollbar is not None:
                scrollbar.setValue(scrollbar.maximum())
        elif self._findings is not None:
            self._findings.appendPlainText(("\n" if self._findings.toPlainText() else "") + exchange)
        self._select_tab(TAB_INDEX["Ask AI"])
        self._set_status(self._with_tokens("Answer received — see the Ask AI tab"))
    elif kind == "analyze_binary":
        if self._triage_text is not None:
            self._triage_text.setPlainText(text)
        self._fill_jump_targets(result)
        self._select_tab(TAB_INDEX["Triage"])
        headline = getattr(getattr(result, "verdict", None), "headline", None)
        self._set_status(self._with_tokens("Binary triage complete" + (" — " + headline if headline else "")))
    elif kind == "obfuscation":
        if self._obfuscation_text is not None:
            self._obfuscation_text.setPlainText(text)
        self._fill_artifacts(result)
        self._select_tab(TAB_INDEX["Obfuscation"])
        self._set_status(self._with_tokens("Obfuscation analysis complete — see the Obfuscation tab"))
    elif kind == "investigate" and isinstance(result, InvestigationResult):
        if self._findings is not None:
            self._findings.setPlainText(text)
        analysis = result.analysis
        suggested = analysis.suggested_name if analysis is not None else None
        if suggested and self._analysis_function is not None:
            self._last_suggestion = (self._analysis_function.address, suggested)
        self._fill_investigation(result)
        self._select_tab(TAB_INDEX["Investigation"])
        self._select_subtab(SUBTAB_INDEX["Attack chain"])
        self._set_status(self._with_tokens("Investigation complete — see the Investigation tab"))
    elif kind == "sweep" and isinstance(result, SweepReport):
        # Batch progress lines were streamed live; only the closing summary line is appended here.
        self._fill_investigation(result.investigation, header=format_sweep_summary(result.summary), trace=(format_sweep_summary(result.summary),))
        self._select_tab(TAB_INDEX["Investigation"])
        self._select_subtab(SUBTAB_INDEX["Attack chain"])
        self._set_status(self._with_tokens(format_sweep_summary(result.summary)))
    elif kind == "report":
        if self._findings is not None:
            self._findings.setPlainText(text)
        self._select_tab(TAB_INDEX["Findings"])
        self._set_status(self._with_tokens("Report saved: {0}".format(getattr(result, "path", ""))))
    else:
        if self._findings is not None:
            self._findings.setPlainText(text)
        suggested = getattr(result, "suggested_name", None)
        if suggested and self._analysis_function is not None:
            self._last_suggestion = (self._analysis_function.address, suggested)
        self._select_tab(TAB_INDEX["Findings"])
        self._set_status(self._with_tokens("{0} complete".format(kind.replace("_", " ").capitalize())))
    self._update_cancel_button()
    self.refresh_changes()
    self.refresh_history()

def _with_tokens(self, text: str) -> str:
    """Append the session token meter to a status line when the controller provides it."""
    if self._actions.token_usage is None:
        return text
    try:
        usage = self._actions.token_usage()
    except Exception:
        return text
    return "{0} ({1})".format(text, usage) if usage else text

def _select_subtab(self, index: int) -> None:
    if self._investigation_tabs is not None:
        self._investigation_tabs.setCurrentIndex(index)

def _fill_investigation(self, result: InvestigationResult, header: Optional[str] = None, trace: Sequence[str] = ()) -> None:
    texts = investigation_tab_texts(result, header)
    if self._chain_text is not None:
        self._chain_text.setPlainText(texts["Attack chain"])
    if self._path_text is not None:
        self._path_text.setPlainText(texts["Analysis path"])
    if self._indicator_text is not None:
        self._indicator_text.setPlainText(texts["Indicators"])
    if self._path_list is not None:
        self._path_list.clear()
        for address, name in investigation_jump_targets(result):
            item = QtWidgets.QListWidgetItem(format_jump_target(address, name))
            item.setData(QtCore.Qt.UserRole, address)
            self._path_list.addItem(item)
    for line in trace:
        self.add_trace(line)

# -- obfuscation tab -------------------------------------------------

def _fill_artifacts(self, report: Any) -> None:
    self._last_obfuscation = report if isinstance(report, ObfuscationReport) else None
    if self._artifact_list is None:
        return
    self._artifact_list.clear()

    return load_function_prompt(self._plugin_root / "prompts" / name)

def _collect_context(self) -> Optional[FunctionAnalysisContext]:
    return self._run_on_ida_thread(lambda: collect_current_function_context(), "MFF_READ")

def _start_function_action(
    self,
    kind: str,
    on_success: Callable[[Any], None],
    on_error: Callable[[str], None],
    options: Mapping[str, Any],
    started: float,
) -> str:
    question = None
    if kind == "ask":
        question = options.get("question")
        if not isinstance(question, str) or not question.strip():
            return "Enter a question first"
        question = question.strip()[:MAX_QUESTION_CHARS]
    context = self._collect_context()
    if context is None and kind != "ask":
        log_event(self._logger, "context_collection", success=False, reason="no_current_function")
        return "No function at current cursor"
    if not self._has_ai_access():
        return self._config.missing_key_message()
    if context is not None:
        log_event(
            self._logger,
            "context_collection",
            success=True,
            kind=kind,
            function_address=hex(context.function.address),
            instructions=len(context.assembly),
            callers=len(context.callers),
            callees=len(context.callees),
        )
    else:
        log_event(self._logger, "context_collection", success=False, reason="no_current_function", kind=kind)
    function = context.function if context is not None else None
    fingerprint = context_fingerprint(context) if context is not None else "analysis-history"
    if question is not None:
        fingerprint = fingerprint + ":" + json.dumps(question)
    if kind in CACHED_ACTIONS and not options.get("force"):
        cached = self._cache.get(kind, function.address, fingerprint)
        if cached is not None:
            log_event(self._logger, "action", kind=kind, success=True, cached=True, duration=0.0)
            on_success(cached)
            return "{0} {1}: (cached)".format(ACTION_LABELS[kind], function.name)
    provider = self._metered(self._provider_factory(), kind)
    extra: Dict[str, Any] = {"tokens_before": self._token_meter.used}
    if kind in ("analyze", "investigate"):
        work = self._agent_work(kind, context, provider, extra)
    elif kind == "suggest_name":
        work = self._naming_work(context, provider, extra)
    elif kind == "capabilities":
        work = self._capability_work(context, provider)
    elif kind == "obfuscation":
        # Whole-binary packing context for the Obfuscation tab: reuse the Analyze Binary seed when
        # the analyst ran it, otherwise collect it once now (bounded, local, cached in the seed).
        seed = self._ensure_triage_seed()
        work = self._obfuscation_work(context, provider, seed.packing if seed is not None else None)
    else:
        work = self._ask_work(context, provider, question or "")
        extra["question"] = question
    self._launch(kind, work, function, fingerprint if kind in CACHED_ACTIONS else None, on_success, on_error, started, extra)
    return "{0} {1}…".format(ACTION_LABELS[kind], function.name)

def _agent_work(
    self, kind: str, context: FunctionAnalysisContext, provider: LLMProvider, extra: Dict[str, Any]
) -> Callable[[], FunctionAnalysis]:
    investigation_prompt = self._prompt("investigation.md")
    schema_prompt = self._prompt(PROMPT_FILES[kind])
    # One cache per session: the initial context is seeded so the agent's
    # first tool calls never repeat the Hex-Rays decompilation.
    cache = ContextCache()
    cache.put(context)
    # SAFE_WRITE tools only create pending proposals (tools/write.py);
    # applying them requires an analyst click in the panel.
    registry = build_read_registry(cache, allow_safe_write=True)
    manager = self.change_manager()
    for tool in build_safe_write_tools(manager):
        registry.register(tool)
    if kind == "investigate":
        # Deterministic decoders; bytes are read on the IDA thread by _execute_ida_tool.
        for tool in build_deobfuscation_tools(make_byte_reader(load_ida_modules())):
            registry.register(tool)
    registry.register(build_pending_changes_tool(manager))
    prompt = build_system_prompt(investigation_prompt, schema_prompt, registry)
    initial = context_to_dict(context)
    if kind == "investigate":
        limits = AgentLimits(
            max_iterations=min(self._config.max_agent_iterations * 2, INVESTIGATE_MAX_ITERATIONS_CAP),
            max_tool_calls=INVESTIGATE_MAX_TOOL_CALLS,
            max_runtime_seconds=INVESTIGATE_MAX_RUNTIME_SECONDS,
        )
        session = AgentSession(INVESTIGATE_REQUEST)
    else:
        limits = AgentLimits(max_iterations=self._config.max_agent_iterations)
        session = AgentSession(ANALYZE_REQUEST)
    extra["session"] = session
    if self._config.show_external_ai_notice:
        session.trace.append("Sending bounded function context to the external {0} API".format(self._config.provider_label))
        self._panel_trace(session.trace[-1])
    agent = InvestigationAgent(
        provider,
        registry,
        prompt,
        limits,
        max_output_tokens=self._config.max_output_tokens,
        temperature=self._config.temperature,
    )
    # The predicates close over ``extra`` and look up the task at call time:
    # ``_launch`` stores the BackgroundTask there before starting it, so a
    # worker that was cancelled and replaced by a newer action keeps seeing
    # *its own* cancelled flag instead of the new task's live one.
    cancelled = lambda: _task_cancelled(extra.get("task"))  # noqa: E731

    def trace(entry: str) -> None:
        if not cancelled():
            self._panel_trace_async(entry)

    def proposal(data: dict) -> None:
        del data
        if not cancelled():
            self._panel_refresh_changes_async()

    def run_agent() -> FunctionAnalysis:
        return agent.run(
            session,
            initial,
            cancelled,
            lambda name, args: self._execute_ida_tool(registry, name, args),
            trace,
            on_proposal=proposal,
        )

    if kind != "investigate":
        return run_agent
    synthesis_prompt = self._prompt(PROMPT_FILES["synthesis"])
    max_output_tokens = self._config.max_output_tokens
    temperature = self._config.temperature

    def investigate() -> InvestigationResult:
        analysis = run_agent()
        if cancelled():
            raise RuntimeError("Investigation cancelled")
        trace("synthesising attack chain, analysis path and indicators")
        # Second model round trip in the same worker; never raises for a model problem.
        return synthesize(
            session, initial, analysis, provider, synthesis_prompt, max_output_tokens=max_output_tokens, temperature=temperature
        )

    return investigate

def _naming_work(
    self, context: FunctionAnalysisContext, provider: LLMProvider, extra: Optional[Dict[str, Any]] = None
) -> Callable[[], Any]:
    prompt = self._prompt(PROMPT_FILES["suggest_name"])
    task_holder: Dict[str, Any] = extra if extra is not None else {}
    address = context.function.address
    local_variables = self._run_on_ida_thread(lambda: collect_local_variables(address), "MFF_READ")
    named_globals = context.referenced_names
    request = build_naming_request(
        context, local_variables, named_globals, prompt, max_output_tokens=self._config.max_output_tokens
    )

    def work():
        raw = provider.generate(request).text
        result = parse_naming_result(raw, context, local_variables, named_globals)
        proposals = suggestions_to_proposals(result, context)
        if _task_cancelled(task_holder.get("task")):
            # A cancelled (possibly superseded) worker must not add proposals to the panel.
            raise RuntimeError("Name suggestion cancelled")
        # Proposals read IDA state (current names), so they are created on IDA's thread.
        self._run_on_ida_thread(lambda: self._create_naming_proposals(proposals), "MFF_READ")
        return result

    return work

def _capability_work(self, context: FunctionAnalysisContext, provider: LLMProvider) -> Callable[[], Any]:
    prompt = self._prompt(PROMPT_FILES["capabilities"])
    signals = local_capability_signals(context)
    request = build_capability_request(context, signals, prompt, max_output_tokens=self._config.max_output_tokens)

    def work():
        report = parse_capability_report(provider.generate(request).text, context, signals)
        return merge_local_and_model(signals, report)

    return work

def _obfuscation_work(self, context: FunctionAnalysisContext, provider: LLMProvider, packing: Any = None) -> Callable[[], Any]:
    prompt = self._prompt(PROMPT_FILES["obfuscation"])
    signals = local_obfuscation_signals(context)
    request = build_obfuscation_request(
        context, signals, prompt, max_output_tokens=self._config.max_output_tokens, temperature=self._config.temperature
    )

    def work():
        report = parse_obfuscation_report(provider.generate(request).text, context, signals)
        # Helper execution reads bytes from the IDB, so it runs on IDA's thread under MFF_READ.
        artifacts = self._run_on_ida_thread(
            lambda: run_suggested_helpers(report, make_byte_reader(load_ida_modules())), "MFF_READ"
        )
        report = with_decoded_artifacts(report, artifacts)
        return with_packing(report, packing) if packing is not None else report

    return work

def _ask_work(self, context: Optional[FunctionAnalysisContext], provider: LLMProvider, question: str) -> Callable[[], str]:
    prompt = self._prompt(PROMPT_FILES["ask"])
    history = self.history_text()
    if len(history) > 18000:
        history = history[-18000:]
    current_function = json.dumps(context_to_dict(context), ensure_ascii=False) if context is not None else "No function is selected."
    request = LLMRequest(
        prompt="Question: {0}\n\nCurrent function context (IDA is ground truth):\n{1}\n\nRecent analysis results and logs:\n{2}".format(
            question, current_function,
            history or "No analysis results recorded yet."
        ),
        system_instruction=prompt,
        max_output_tokens=self._config.max_output_tokens,
        temperature=self._config.temperature,
    )

    def work() -> str:
        text = provider.generate(request).text
        answer = text.strip() if isinstance(text, str) else ""
        if not answer:
            raise RuntimeError("The model returned an empty answer")
        if len(answer) > MAX_ANSWER_CHARS:
            answer = answer[: MAX_ANSWER_CHARS - 1] + "…"
        return answer

    return work

# -- whole-binary triage, verdict and sweep -------------------------------

def _collect_binary(self) -> Tuple[Any, Any]:
    """IDA thread (MFF_READ): the overview plus bounded byte statistics (entropy sampling)."""
    overview = collect_binary_overview()

"""Provider-neutral request, response, error, and interface definitions."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Iterator, Optional, Tuple


class LLMProviderError(RuntimeError):
    """A safe provider error suitable for displaying without credentials."""


class MissingApiKeyError(LLMProviderError):
    """Raised only when an analyst initiates an LLM operation without a key."""


class UnsupportedProviderFeatureError(LLMProviderError):
    """Raised for deliberately deferred provider capabilities."""


@dataclass(frozen=True)
class LLMRequest:
    prompt: str
    system_instruction: Optional[str] = None
    max_output_tokens: Optional[int] = None
    temperature: Optional[float] = None
    response_mime_type: Optional[str] = None

    def __post_init__(self) -> None:
        if not isinstance(self.prompt, str) or not self.prompt.strip():
            raise ValueError("prompt must be a non-empty string")
        if self.system_instruction is not None and not isinstance(self.system_instruction, str):
            raise ValueError("system_instruction must be a string when provided")
        if self.max_output_tokens is not None and (
            not isinstance(self.max_output_tokens, int) or self.max_output_tokens <= 0
        ):
            raise ValueError("max_output_tokens must be a positive integer when provided")
        if self.temperature is not None and (
            not isinstance(self.temperature, (int, float)) or isinstance(self.temperature, bool)
        ):
            raise ValueError("temperature must be a number when provided")
        if self.response_mime_type is not None and not isinstance(self.response_mime_type, str):
            raise ValueError("response_mime_type must be a string when provided")


@dataclass(frozen=True)
class LLMResponse:
    text: str
    model: str
    finish_reason: Optional[str] = None
    # ``{"input": int, "output": int}`` when the provider reported token usage, else None.
    usage: Optional[dict] = None


def usage_from(mapping: object, input_key: str, output_key: str) -> Optional[dict]:
    """Normalise a provider usage block to ``{"input", "output"}``; ``None`` when absent or malformed."""
    if not isinstance(mapping, dict):
        return None
    input_tokens = mapping.get(input_key)
    output_tokens = mapping.get(output_key)
    if isinstance(input_tokens, bool) or isinstance(output_tokens, bool):
        return None
    if not isinstance(input_tokens, int) or not isinstance(output_tokens, int):
        return None
    if input_tokens < 0 or output_tokens < 0:
        return None
    return {"input": input_tokens, "output": output_tokens}


@dataclass(frozen=True)
class ProviderHealth:
    available: bool
    model: str
    detail: Optional[str] = None


class LLMProvider(ABC):
    """Stable internal boundary; provider schemas remain in adapters."""

    @abstractmethod
    def generate(self, request: LLMRequest) -> LLMResponse:
        raise NotImplementedError

    def generate_with_tools(self, request: LLMRequest, tools: object) -> LLMResponse:
        del request, tools
        raise UnsupportedProviderFeatureError("Tool calling is not implemented in Phase 3")

    def stream(self, request: LLMRequest) -> Iterator[str]:
        del request
        raise UnsupportedProviderFeatureError("Streaming is not implemented in Phase 3")

    @abstractmethod
    def health_check(self) -> ProviderHealth:
        raise NotImplementedError

    def list_models(self) -> Tuple[str, ...]:
        """Model ids the provider advertises (bounded); adapters override this."""
        raise UnsupportedProviderFeatureError("Model listing is not supported by this provider")

