"""Persistent local analysis database (SQLite, standard library only).

Two tables, both scoped to one binary (SHA-256 of the input file):

``responses``
    Validated model responses keyed by a digest of the exact request (system
    prompt + prompt + parameters). ``CachingProvider`` replays them, so
    re-running *any* tab on an unchanged function costs no tokens: the plugin
    re-parses the stored text with the same local validators. A change to the
    function (rename, retype, patched bytes) changes its context and therefore
    the request digest, so stale answers are never replayed.

``functions``
    One row per (function address, analysis kind) with the latest summary and
    JSON payload. The Report tab and Ask AI read these before asking a model.

The database lives next to the IDB (``<idb>.ai_analysis.sqlite``). Nothing in
it leaves the machine. All methods are thread-safe and never raise for
storage problems: a broken or locked database degrades to "no cache".
"""

from __future__ import annotations

import hashlib
import json
import sqlite3
import threading
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from ida_ai_malware_analyst_plugin.llm.base import LLMProvider, LLMRequest, LLMResponse, ProviderHealth

SCHEMA_VERSION = 1
MAX_RESPONSE_CHARS = 512 * 1024
MAX_PAYLOAD_CHARS = 256 * 1024

_SCHEMA = (
    "CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS responses ("
    " binary_id TEXT NOT NULL, digest TEXT NOT NULL, label TEXT NOT NULL, model TEXT, text TEXT NOT NULL,"
    " created_at REAL NOT NULL, hits INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (binary_id, digest))",
    "CREATE TABLE IF NOT EXISTS functions ("
    " binary_id TEXT NOT NULL, address INTEGER NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, origin TEXT,"
    " summary TEXT, payload TEXT, fingerprint TEXT, updated_at REAL NOT NULL, PRIMARY KEY (binary_id, address, kind))",
    "CREATE INDEX IF NOT EXISTS functions_name ON functions (binary_id, name)",
)


