        rows = self._execute("SELECT text, model FROM responses WHERE binary_id = ? AND digest = ?", (self.binary_id, digest))
        if not rows:
            return None
        self._execute("UPDATE responses SET hits = hits + 1 WHERE binary_id = ? AND digest = ?", (self.binary_id, digest))
        return rows[0][0], rows[0][1] or ""

    def put_response(self, digest: str, label: str, model: str, text: str) -> None:
        if not isinstance(text, str) or not text.strip() or len(text) > MAX_RESPONSE_CHARS:
            return
        self._execute(
            "INSERT OR REPLACE INTO responses (binary_id, digest, label, model, text, created_at, hits) VALUES (?, ?, ?, ?, ?, ?, 0)",
            (self.binary_id, digest, label, model or "", text, time.time()),
        )

    # -- functions --------------------------------------------------------

    def put_function(
        self,
        address: int,
        kind: str,
        name: str,
        summary: str,
        payload: Optional[Dict[str, Any]] = None,
        origin: str = "",
        fingerprint: str = "",
    ) -> None:
        try:
            encoded = json.dumps(payload or {}, ensure_ascii=False, default=str)
        except (TypeError, ValueError):
            encoded = "{}"
        if len(encoded) > MAX_PAYLOAD_CHARS:
            encoded = json.dumps({"truncated": True, "summary": (summary or "")[:4000]})
        self._execute(
            "INSERT OR REPLACE INTO functions (binary_id, address, kind, name, origin, summary, payload, fingerprint, updated_at)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (self.binary_id, int(address), kind, name or "", origin or "", summary or "", encoded, fingerprint or "", time.time()),
        )

    def functions(self, kinds: Optional[Iterable[str]] = None) -> Tuple[FunctionRecord, ...]:
        kind_list = list(kinds or ())
        if kind_list:
            marks = ",".join("?" for _ in kind_list)
            rows = self._execute(
                "SELECT address, kind, name, origin, summary, payload, fingerprint, updated_at FROM functions"
                " WHERE binary_id = ? AND kind IN ({0}) ORDER BY address".format(marks),
                [self.binary_id] + kind_list,
            )
        else:
            rows = self._execute(
                "SELECT address, kind, name, origin, summary, payload, fingerprint, updated_at FROM functions"
                " WHERE binary_id = ? ORDER BY address",
                (self.binary_id,),
            )
        return tuple(_record(row) for row in rows)

    def function(self, address: int, kinds: Iterable[str] = ()) -> Tuple[FunctionRecord, ...]:
        return tuple(item for item in self.functions(kinds) if item.address == address)

    def find_functions(self, text: str) -> Tuple[FunctionRecord, ...]:
        """Records whose function name or ``0x`` address appears in ``text`` (case-insensitive)."""
        if not text:
            return ()
        lowered = text.lower()
        output: List[FunctionRecord] = []
        for record in self.functions():
            name = (record.name or "").lower()
            address = "0x{0:x}".format(record.address)
            if (name and len(name) >= 4 and name in lowered) or address in lowered or "{0:x}".format(record.address) in lowered.split():
                output.append(record)
        return tuple(output)

    def counts(self) -> Dict[str, int]:
        responses = self._execute("SELECT COUNT(*) FROM responses WHERE binary_id = ?", (self.binary_id,))
        functions = self._execute("SELECT COUNT(DISTINCT address) FROM functions WHERE binary_id = ?", (self.binary_id,))
        return {
            "responses": int(responses[0][0]) if responses else 0,
            "functions": int(functions[0][0]) if functions else 0,
        }

    def clear(self) -> int:
        before = self.counts()
        self._execute("DELETE FROM responses WHERE binary_id = ?", (self.binary_id,))
        self._execute("DELETE FROM functions WHERE binary_id = ?", (self.binary_id,))
        return before["responses"] + before["functions"]


def _record(row: Tuple[Any, ...]) -> FunctionRecord:
    try:
        payload = json.loads(row[5] or "{}")
    except (TypeError, ValueError):
        payload = {}
    return FunctionRecord(
        address=int(row[0]), kind=str(row[1]), name=str(row[2] or ""), origin=str(row[3] or ""), summary=str(row[4] or ""),
        payload=payload if isinstance(payload, dict) else {}, fingerprint=str(row[6] or ""), updated_at=float(row[7] or 0.0),
    )


class CachingProvider(LLMProvider):
    """Replays stored responses for identical requests; new responses wait for ``commit``.

    Responses are only persisted after the action that requested them
    succeeded (the controller calls ``commit``), so a reply the validators
    rejected is never replayed. Hits report zero token usage.
    """

    def __init__(self, inner: LLMProvider, store: Optional[AnalysisStore], label: str = "", model_hint: str = "") -> None:
        self.inner = inner
        self.store = store
        self.label = label
        self.model_hint = model_hint
        self.hits = 0
        self.misses = 0
        self._pending: List[Tuple[str, str, str]] = []
        self._lock = threading.Lock()

    def generate(self, request: LLMRequest) -> LLMResponse:
        digest = request_digest(request, self.model_hint)
        if self.store is not None and self.store.available:
            stored = self.store.get_response(digest)
            if stored is not None:
                with self._lock:
                    self.hits += 1
                return LLMResponse(text=stored[0], model=stored[1] or "local-cache", finish_reason="cached", usage={"input": 0, "output": 0})
        response = self.inner.generate(request)
        with self._lock:
            self.misses += 1
            self._pending.append((digest, getattr(response, "model", "") or "", response.text))
        return response

    def commit(self) -> int:
        with self._lock:
            pending, self._pending = self._pending, []
        if self.store is None or not self.store.available:
            return 0
        for digest, model, text in pending:
            self.store.put_response(digest, self.label, model, text)
        return len(pending)

    def discard(self) -> None:
        with self._lock:
            self._pending = []

    def generate_with_tools(self, request: LLMRequest, tools: object) -> LLMResponse:
        return self.inner.generate_with_tools(request, tools)

    def stream(self, request: LLMRequest):
        return self.inner.stream(request)

    def health_check(self) -> ProviderHealth:
        return self.inner.health_check()

    def list_models(self) -> Tuple[str, ...]:
        return self.inner.list_models()


__all__ = ["AnalysisStore", "CachingProvider", "FunctionRecord", "request_digest"]

