def _sample_metadata(path: Optional[str], triage: Mapping[str, Any]) -> dict:
    file_type = triage.get("file_type") or "Unknown"
    architecture = triage.get("architecture") or "Unknown"
    meta = {"File type": str(file_type), "Architecture": str(architecture), "File size": "Unavailable",
            "Entry point": "Unavailable", "SHA256": "Unavailable", "Digital signature": "Unknown"}
    if not path:
        return meta
    try:
        target = Path(path)
        size = target.stat().st_size
        meta["File size"] = "{0} bytes".format(size)
        digest = hashlib.sha256()
        with target.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
        meta["SHA256"] = digest.hexdigest()
        with target.open("rb") as handle:
            header = handle.read(4096)
        pe = _pe_metadata(header)
        if pe:
            meta["Entry point"] = "RVA {0} / VA {1}".format(_hex(pe["rva"]), _hex(pe["image_base"] + pe["rva"]))
            meta["Digital signature"] = "Signed (certificate present; validity not verified)" if pe["signed"] else "Unsigned"
            if str(file_type).lower() == "unknown":
                meta["File type"] = "PE32+ EXE" if pe["is_64"] else "PE32 EXE"
            if str(architecture).lower() == "unknown":
                meta["Architecture"] = "x64" if pe["is_64"] else "x86"
        return meta
    except (OSError, ValueError, struct.error):
        return meta


def _pe_metadata(data: bytes) -> Optional[dict]:
    if len(data) < 64 or data[:2] != b"MZ":
        return None
    pe_offset = struct.unpack_from("<I", data, 0x3C)[0]
    if pe_offset + 24 > len(data) or data[pe_offset:pe_offset + 4] != b"PE\0\0":
        return None
    optional = pe_offset + 24
    magic = struct.unpack_from("<H", data, optional)[0]
    is_64 = magic == 0x20B
    if magic not in (0x10B, 0x20B):
        return None
    entry_rva = struct.unpack_from("<I", data, optional + 16)[0]
    image_base = struct.unpack_from("<Q" if is_64 else "<I", data, optional + (24 if is_64 else 28))[0]
    directory_count_offset = optional + (108 if is_64 else 92)
    directory_offset = optional + (112 if is_64 else 96)
    signed = False
    if directory_count_offset + 4 <= len(data) and struct.unpack_from("<I", data, directory_count_offset)[0] > 4:
        certificate = directory_offset + 4 * 8
        if certificate + 8 <= len(data):
            signed = struct.unpack_from("<II", data, certificate) != (0, 0)
    return {"rva": entry_rva, "image_base": image_base, "signed": signed, "is_64": is_64}


