def change_manager(self) -> ChangeManager:
    """The single mutation authority; created lazily over the native adapter."""
    if self._change_manager is None:
        adapter = MetadataSafeWrites(IdaSafeWrites())
        self._change_manager = ChangeManager(adapter.read, adapter.write, normalizer=adapter.normalize)
    return self._change_manager

def propose_change(
    self,
    operation: str,
    address: int,
    new_value: str,
    reason: str = "",
    evidence: Tuple[str, ...] = (),
    confidence: Optional[float] = None,
    source: str = "analyst",
    metadata: Optional[Mapping[str, Any]] = None,
) -> ProposedChange:
    """Create a PENDING proposal. Reads IDA state, so it runs under MFF_READ."""
    manager = self.change_manager()
    try:
        change = self._run_on_ida_thread(
            lambda: manager.propose(operation, address, new_value, reason, evidence, confidence, metadata), "MFF_READ"
        )
    except ValueError as exc:
        log_event(self._logger, "change_proposal_rejected", operation=operation, address=hex(address), source=source, error=str(exc))
        raise
    self._log_change("change_proposed", change, source=source)
    return change

def approve_change(self, change_id: str) -> ProposedChange:
    """Analyst approval: revalidate, write, verify and audit on IDA's main thread (MFF_WRITE)."""
    manager = self.change_manager()
    try:
        change = self._run_on_ida_thread(lambda: manager.approve(change_id), "MFF_WRITE")
    except (KeyError, ValueError) as exc:
        self._log_change_failure("change_approve_failed", manager, change_id, exc)
        raise
    self._log_change("change_approved", change)
    self._record_change_history(change)
    self._cache.invalidate(change.address)
    return change

def reject_change(self, change_id: str) -> ProposedChange:
    change = self.change_manager().reject(change_id)
    self._log_change("change_rejected", change)
    return change

def rollback_change(self, change_id: str) -> ProposedChange:
    """Restore the recorded prior value on IDA's main thread (MFF_WRITE)."""
    manager = self.change_manager()
    try:
        change = self._run_on_ida_thread(lambda: manager.rollback(change_id), "MFF_WRITE")
    except (KeyError, ValueError) as exc:
        self._log_change_failure("change_rollback_failed", manager, change_id, exc)
        raise
    self._log_change("change_rolled_back", change)
    self._record_change_history(change)
    self._cache.invalidate(change.address)
    return change

def pending_changes(self) -> Tuple[ProposedChange, ...]:
    return self.change_manager().pending()

def listed_changes(self) -> Tuple[ProposedChange, ...]:
    """Pending and applied (rollback-able) changes, oldest first, for the panel."""
    changes = [change for change in self.change_manager().changes.values() if change.status in LISTED_STATES]
    return tuple(sorted(changes, key=lambda change: change.created_at))

def audit_entries(self) -> Tuple[dict, ...]:
    return tuple(dict(entry) for entry in self.change_manager().audit)

def _log_change(self, event: str, change: ProposedChange, **extra: object) -> None:
    log_event(
        self._logger,
        event,
        change_id=change.change_id,
        operation=change.operation,
        address=hex(change.address),
        status=change.status.value,
        old=_log_value(change.old_value),
        new=_log_value(change.proposed_value),
        **extra
    )

def _log_change_failure(self, event: str, manager: ChangeManager, change_id: str, error: Exception) -> None:
    change = manager.changes.get(change_id)
    log_event(
        self._logger,
        event,
        change_id=change_id,
        operation=change.operation if change else "unknown",
        status=change.status.value if change else "unknown",
        error=_log_value(str(error)),
    )

def _record_change_history(self, change: ProposedChange) -> None:
    summary = "{0} {1}: {2} → {3}".format(
        change.status.value, change.operation, _log_value(change.old_value), _log_value(change.proposed_value)
    )
    payload = {
        "change_id": change.change_id,
        "operation": change.operation,
        "address": change.address,
        "old_value": change.old_value,
        "new_value": change.proposed_value,
        "status": change.status.value,
    }
    try:
        self._history.record("change", change.address, None, summary, payload)
    except (TypeError, ValueError) as exc:
        log_event(self._logger, "history_record_failed", kind="change", error=str(exc))

def _propose_suggested_name(self, function: FunctionDetails, suggested_name: str) -> Optional[ProposedChange]:
    """Turn a validated analysis suggestion into a PENDING rename proposal, or skip it."""
    if suggested_name == function.name:
        log_event(self._logger, "suggested_name_skipped", address=hex(function.address), reason="unchanged")
        return None
    try:
        ChangeManager.validate_value("rename_function", suggested_name)
    except ValueError:
        log_event(self._logger, "suggested_name_skipped", address=hex(function.address), reason="invalid_identifier")
        return None
    if self._already_pending("rename_function", function.address, suggested_name):
        log_event(self._logger, "suggested_name_skipped", address=hex(function.address), reason="already_pending")
        return None
    try:
        return self.propose_change("rename_function", function.address, suggested_name, "Suggested by AI function analysis", source="analysis")
    except (ValueError, RuntimeError):
        return None

def _already_pending(self, operation: str, address: int, value: str, current_name: Optional[str] = None) -> bool:
    for change in self.pending_changes():
        if change.operation != operation or change.address != address or change.proposed_value != value:
            continue
        if current_name is None or change.metadata.get("current_name") == current_name:
            return True
    return False

def _create_naming_proposals(self, proposals: Sequence[Mapping[str, Any]]) -> List[ProposedChange]:
    """Create PENDING proposals from validated naming suggestions (IDA thread, MFF_READ).

    Nothing is applied: each proposal waits for an analyst click in the panel.
    """
    manager = self.change_manager()
    created: List[ProposedChange] = []
    for item in proposals:
        operation = item.get("operation")
        address = item.get("address")
        value = item.get("value")
        current_name = item.get("current_name")
        if not isinstance(operation, str) or not isinstance(address, int) or not isinstance(value, str):
            continue
        if self._already_pending(operation, address, value, current_name if operation == "rename_variable" else None):
            log_event(self._logger, "naming_proposal_skipped", operation=operation, address=hex(address), reason="already_pending")
            continue
        metadata = {"current_name": current_name, "new_name": value} if operation == "rename_variable" else None
        reason = item.get("reason") or "Suggested by AI naming analysis"
        evidence = tuple(str(entry) for entry in item.get("evidence", ()))
        try:
            change = manager.propose(operation, address, value, reason, evidence, item.get("confidence"), metadata)
        except ValueError as exc:
            log_event(self._logger, "naming_proposal_skipped", operation=operation, address=hex(address), reason=str(exc))
            continue
        self._log_change("change_proposed", change, source="naming")
        created.append(change)
    return created

def propose_decoded_comments(self, report: Any) -> int:
    """Queue one PENDING ``add_comment`` proposal per decoded artifact with a target address.

    Called from the Obfuscation tab's "Propose comments" button (UI thread);
    each proposal reads IDA state through ``propose_change`` (MFF_READ).
    Nothing is written: every comment waits for Approve. Returns the number queued.
    """
    if not isinstance(report, ObfuscationReport):
        return 0
    queued = 0
    for item in decoded_artifacts_to_comment_proposals(report):
        address = item.get("address")
        value = item.get("value")
        if not isinstance(address, int) or not isinstance(value, str):
            continue
        if self._already_pending("add_comment", address, value):
            continue
        try:
            self.propose_change(
                "add_comment",
                address,
                value,
                reason=str(item.get("reason") or "Decoded locally by a deterministic helper"),
                evidence=tuple(str(entry) for entry in item.get("evidence", ())),
                confidence=item.get("confidence"),
                source="obfuscation",
            )
        except (ValueError, RuntimeError) as exc:
            log_event(self._logger, "decoded_comment_skipped", address=hex(address), reason=_log_value(str(exc)))
            continue
        queued += 1
    log_event(self._logger, "decoded_comments_proposed", count=queued, function=hex(report.function_address))
    self._panel_refresh_changes()
    return queued

# -- action runner ------------------------------------------------------

def is_running(self) -> bool:
    return self._running_kind is not None

def token_usage_text(self) -> str:
    """``~N tokens this session`` for the panel status line."""
    return "{0} this session".format(format_tokens(self._token_meter.used))

def token_meter(self) -> TokenBudget:
    return self._token_meter

def _metered(self, provider: LLMProvider, label: str, on_record: Optional[Callable[[Any], None]] = None) -> LLMProvider:
    """Wrap a provider so every call is charged to the session meter (and optionally a second budget)."""
    return MeteredProvider(provider, self._token_meter, on_record=on_record, logger=self._logger, label=label)

def running_kind(self) -> Optional[str]:
    return self._running_kind

def history_text(self) -> str:
    return format_history(self._history.entries())

def history(self) -> AnalysisHistory:
    return self._history

def clear_cache(self) -> int:
    count = self._cache.invalidate()
    log_event(self._logger, "cache_cleared", entries=count)
    return count

def triage_targets(self) -> Tuple[Tuple[int, str], ...]:
    return self._triage_targets

