def listed_changes(self, include_applied: bool = False) -> Tuple[ProposedChange, ...]:
    """Changes awaiting a decision, oldest first; applied ones only when the analyst asks (for rollback).

    Approved, rejected, failed and rolled-back items leave the list as soon as they are
    decided, so a new naming pass never shows yesterday's work. Their record stays in the
    History tab and the audit log.
    """
    states = APPLIED_LISTED_STATES if include_applied else LISTED_STATES
