def _metered(self, provider: LLMProvider, label: str, on_record: Optional[Callable[[Any], None]] = None) -> LLMProvider:
    """Session-metered provider behind the local response cache.

    ``CachingProvider`` sits outside the meter, so a replayed response is never
    charged. New responses are held until the action succeeds
    (``_commit_caches``); a reply the validators rejected is discarded.
    """
    metered = MeteredProvider(provider, self._token_meter, on_record=on_record, logger=self._logger, label=label)
    store = self._analysis_store()
    if store is None:
        return metered
    caching = CachingProvider(metered, store, label=label, model_hint=str(getattr(self._config, "active_model", "") or ""))
    self._open_caches.append(caching)
    return caching

def _analysis_store(self) -> Optional[AnalysisStore]:
    """The local database of the current IDB (opened on first use, reopened when the IDB changes)."""
    try:
        key, path = self._run_on_ida_thread(self._store_location, "MFF_READ")
    except Exception as exc:  # no IDA / no IDB: caching simply stays off
        log_event(self._logger, "store_unavailable", error=_log_value(str(exc)))
        return None
    if not key:
        return None
    if self._store is not None and self._store_key == key and self._store.available:
        return self._store
    if self._store is not None:
        self._store.close()
    self._store = AnalysisStore(path, key, logger=self._logger)
    self._store_key = key
    return self._store if self._store.available else None

def _store_location(self) -> Tuple[Optional[str], Path]:
    """``(binary id, database path)``: SHA-256 of the input file, database next to the IDB."""
    modules = load_ida_modules()
    binary_id: Optional[str] = None
    for module in (modules.nalt, modules.idaapi):
        getter = getattr(module, "retrieve_input_file_sha256", None) if module is not None else None
        if callable(getter):
            try:
                value = getter()
            except Exception:
                value = None
            if isinstance(value, (bytes, bytearray)) and value:
                binary_id = bytes(value).hex()
                break
            if isinstance(value, str) and value:
                binary_id = value.lower()
                break
    name, directory = self._default_report_location()
    if binary_id is None:
        input_path = self._input_file_path()
        binary_id = "path:" + (input_path or name)
    idb_text = None
    idaapi = modules.idaapi
    if idaapi is not None and callable(getattr(idaapi, "get_path", None)) and hasattr(idaapi, "PATH_TYPE_IDB"):
        idb_text = self._first_path((lambda: idaapi.get_path(idaapi.PATH_TYPE_IDB),))
    stem = Path(idb_text).name if idb_text else name
    return binary_id, Path(directory) / (stem + ".ai_analysis.sqlite")

def _commit_caches(self, success: bool) -> None:
    caches, self._open_caches = self._open_caches, []
    hits = 0
    for cache in caches:
        hits += cache.hits
        if success:
            cache.commit()
        else:
            cache.discard()
    if hits:
        log_event(self._logger, "cache_replayed", responses=hits)

def store_status_text(self) -> str:
    store = self._store
    if store is None or not store.available:
        return "local analysis database: not open"
    counts = store.counts()
    return "local analysis database: {0} cached responses, {1} analysed functions ({2})".format(
        counts["responses"], counts["functions"], store.path.name
    )

