def _record_history(self, kind: str, function: Optional[FunctionDetails], result: Any, extra: Mapping[str, Any]) -> None:
    history_kind = HISTORY_KIND_BY_ACTION.get(kind)
    if history_kind is None:
        return
    summary, payload = self._history_payload(kind, result, extra)
    before = extra.get("tokens_before")
    if isinstance(before, int) and not isinstance(before, bool):
        payload["tokens"] = {"action": max(0, self._token_meter.used - before), "session": self._token_meter.used}
    try:
        self._history.record(
            history_kind,
            function.address if function is not None else None,
            function.name if function is not None else None,
            summary,
            payload,
        )
    except (TypeError, ValueError) as exc:
        log_event(self._logger, "history_record_failed", kind=history_kind, error=_log_value(str(exc)))

