def format_sweep_findings(result: Any) -> str:
    """Findings-tab view of "Investigate top N": what the binary is, from its highest-value functions.

    One conclusion block, then one line per function (address, name, strongest
    capability, one-sentence role). The full chain, path and IOCs stay in the
    Investigation tab, so nothing is printed twice.
    """
    functions = tuple(getattr(result, "functions", ()) or ())
    investigation = getattr(result, "investigation", None)
    categories: dict = {}
    for item in functions:
        for cap in item.capabilities:
            if cap.basis == "observed":
                categories[cap.category] = categories.get(cap.category, 0) + 1
            else:
                categories.setdefault(cap.category, 0)
    lines = ["Investigate top {0} — conclusion".format(len(functions) or getattr(result.summary, "functions_planned", 0)), ""]
    summary = str(getattr(investigation, "summary", "") or "").strip()
    if summary:
        lines.append(summary)
        lines.append("")
    if categories:
        ordered = sorted(categories.items(), key=lambda pair: (-pair[1], -_SWEEP_CATEGORY_WEIGHT.get(pair[0], 1), pair[0]))
        lines.append("Capabilities (observed / inferred): " + ", ".join(
            "{0}{1}".format(name, " ×{0}".format(count) if count else " (inferred)") for name, count in ordered
        ))
        lines.append("")
    lines.append("Highest-value functions:")
    if not functions:
        lines.append("  (no function analysis returned)")

    def weight(item: Any) -> tuple:
        observed = [cap for cap in item.capabilities if cap.basis == "observed"]
        return (-(len(observed) * 2 + len(item.capabilities)), -item.analysis.behavior_confidence, item.address)

    for item in sorted(functions, key=weight):
        caps = [cap for cap in item.capabilities if cap.basis == "observed"] or list(item.capabilities)
        cap_text = caps[0].capability if caps else "-"
        role = " ".join(item.analysis.summary.split())
        if len(role) > 110:
            role = role[:109] + "…"
        lines.append("  0x{0:X}  {1:<32} [{2}] {3}".format(item.address, item.name[:32], cap_text[:40], role))
    lines.append("")
    lines.append(format_sweep_summary(result.summary))
    lines.append("Attack chain, analysis path and indicators: Investigation tab. Full report: Report button.")
    return "\n".join(lines)


