"""Version-tolerant, isolated access to optional IDA and Hex-Rays APIs."""

from __future__ import annotations

import importlib
from dataclasses import dataclass
from types import ModuleType
from typing import Optional

from ida_ai_malware_analyst_plugin.core.models import FunctionContext


@dataclass(frozen=True)
class IdaModules:
    kernwin: Optional[ModuleType]
    funcs: Optional[ModuleType]
    name: Optional[ModuleType]
    idaapi: Optional[ModuleType]
    hexrays: Optional[ModuleType]
    idautils: Optional[ModuleType] = None
    idc: Optional[ModuleType] = None
    ida_lines: Optional[ModuleType] = None
    bytes: Optional[ModuleType] = None
    nalt: Optional[ModuleType] = None
    typeinf: Optional[ModuleType] = None
    gdl: Optional[ModuleType] = None

    @property
    def available(self) -> bool:
        return all((self.kernwin, self.funcs, self.name, self.idaapi))


def _optional_module(name: str) -> Optional[ModuleType]:
    try:
        return importlib.import_module(name)
    except ImportError:
        return None


def load_ida_modules() -> IdaModules:
    """Load IDA modules only when running in IDAPython."""
    return IdaModules(
        kernwin=_optional_module("ida_kernwin"),
        funcs=_optional_module("ida_funcs"),
        name=_optional_module("ida_name"),
        idaapi=_optional_module("idaapi"),
        hexrays=_optional_module("ida_hexrays"),
        idautils=_optional_module("idautils"),
        idc=_optional_module("idc"),
        ida_lines=_optional_module("ida_lines"),
        bytes=_optional_module("ida_bytes"),
        nalt=_optional_module("ida_nalt"),
        typeinf=_optional_module("ida_typeinf"),
        gdl=_optional_module("ida_gdl"),
    )


def get_current_function(modules: Optional[IdaModules] = None) -> Optional[FunctionContext]:
    """Return the function under IDA's cursor, or ``None`` when unavailable."""
    loaded = modules or load_ida_modules()
    if not loaded.available:
        return None
    try:
        ea = loaded.kernwin.get_screen_ea()
        badaddr = loaded.idaapi.BADADDR
        if ea == badaddr:
            return None
        function = loaded.funcs.get_func(ea)
        if function is None:
            return None

