    """``path=None`` (the plugin default) keeps the database in memory for this IDA session only."""
    self.path = Path(path) if path is not None else None
    self.binary_id = binary_id or "unknown"
    self._logger = logger
    self._lock = threading.RLock()
    self._connection: Optional[sqlite3.Connection] = None
    self.available = self._open()

@property
def location_label(self) -> str:
    return self.path.name if self.path is not None else "in memory, cleared when IDA closes"

