    # A database file written by an earlier build next to the IDB is removed.
    self._remove_legacy_store(path)
    self._store = AnalysisStore(None, key, logger=self._logger)
    self._store_key = key
    return self._store if self._store.available else None

def _remove_legacy_store(self, path: Path) -> None:
    for suffix in ("", "-wal", "-shm", "-journal"):
        candidate = Path(str(path) + suffix)
        try:
            if candidate.is_file():
                candidate.unlink()
                log_event(self._logger, "legacy_store_removed", path=_log_value(candidate.name))
        except OSError as exc:
            log_event(self._logger, "legacy_store_remove_failed", error=_log_value(str(exc)))

def _discard_store(self) -> None:
    """Forget everything stored for the file of this session (called when IDA closes the database)."""
    caches, self._open_caches = self._open_caches, []
    for cache in caches:
        cache.discard()
    store, self._store = self._store, None
    self._store_key = None
    if store is not None:
        count = store.clear()
        store.close()
        log_event(self._logger, "session_store_cleared", entries=count)

