LITERAL_LANGUAGES = frozenset({"go", "rust", "nim"})
MAX_LITERAL_FUNCTIONS = 4000


def _with_recovered_literals(
    modules: IdaModules,
    functions: Tuple[FunctionSummary, ...],
    strings: Tuple[StringInfo, ...],
    segment_index: "_SegmentIndex",
    limits: TriageLimits,
) -> Tuple[Tuple[FunctionSummary, ...], Tuple[StringInfo, ...]]:
    from ida_ai_malware_analyst_plugin.ida.literal_reader import recover_function_literals

    author = [item.address for item in functions if item.origin in ANALYSABLE_ORIGINS and item.detailed and not item.is_thunk]
    if not author:
        return functions, strings

    def is_data(address: int) -> bool:
        segment = segment_index.find(address)
        return segment is not None and not segment.executable

    try:
        recovered = recover_function_literals(modules, author, is_data, max_functions=MAX_LITERAL_FUNCTIONS,
                                              max_instructions=limits.max_instructions_per_function)
    except _IDA_ERRORS:
        return functions, strings
    if not recovered:
        return functions, strings
    known = {item.address for item in strings}
    extra: List[StringInfo] = []
    per_function: Dict[int, List[str]] = {}
    for start, literals in recovered:
        for literal in literals:
            per_function.setdefault(start, []).append(literal.value)
            if literal.address not in known and len(strings) + len(extra) < limits.max_strings + MAX_LITERAL_STRINGS:
                known.add(literal.address)
                extra.append(StringInfo(address=literal.address, value=literal.value))
    updated: List[FunctionSummary] = []
    for item in functions:
        values = per_function.get(item.address)
        if not values:
            updated.append(item)
            continue
        merged = list(item.referenced_strings)
        for value in values:
            if value not in merged and len(merged) < limits.max_strings_per_function:
                merged.append(value)
        updated.append(replace(item, referenced_strings=tuple(merged), string_count=item.string_count + len(values)))
    return tuple(updated), tuple(strings) + tuple(extra)


