    """True when DllMain (or a function it calls directly) changes page protection and targets a module.

    This is the static footprint of a side-loaded DLL that patches its host's
    entry point (``GetModuleHandle(NULL)`` + ``VirtualProtect`` + a write).
    """
    functions = tuple(getattr(overview, "functions", ()) or ())
    by_address = {getattr(item, "address", None): item for item in functions}
    roots = [item for item in functions if str(getattr(item, "name", "")).lstrip("_") in tuple(name.lstrip("_") for name in _DLLMAIN_NAMES)]
    candidates = list(roots)
    for root in roots:
        candidates.extend(by_address[callee] for callee in getattr(root, "callees", ()) if callee in by_address)
    for item in candidates:
        names = " ".join(str(api) for api in getattr(item, "imports_called", ()) or ())
        if any(api in names for api in _PROTECT_APIS) and any(api in names for api in _HOST_APIS):
            return True
    return False


