    if not isinstance(top, int) or isinstance(top, bool) or not 1 <= top <= 256:
        raise DeobfuscationInputError("top must be 1..256")
    charset = _PRINTABLE if expected_charset is None else frozenset(int(c) & 0xFF for c in expected_charset)
    sample = payload[:MAX_STACK_STRING_BYTES]
    scored: List[Tuple[int, float, str]] = []
    for key in range(256):
        decoded = bytes(value ^ key for value in sample)
        scored.append((key, text_score(decoded, charset), printable_preview(decoded)))
    scored.sort(key=lambda item: (-item[1], item[0]))
    return tuple(scored[:top])


# --------------------------------------------------------------------------- #
# Stack strings
# --------------------------------------------------------------------------- #


@dataclass(frozen=True)
class StackString:
    start_address: int
    end_address: int
    text: str
    encoding: str  # "ascii" or "utf-16le"
    byte_count: int


def _stack_offset(operand: str) -> Optional[Tuple[str, int]]:
    """Return (base register, signed displacement) for ``[rbp+var_20]``-style operands."""
    bare, _ = _strip_size_prefix(operand)
    match = _STACK_OPERAND_PATTERN.match(bare)
    if not match:
        return None
    base = match.group("base")
    disp_text = match.group("disp")
    sign = match.group("sign") or "+"
    if disp_text is None:
        return base, 0
    var = _VAR_PATTERN.match(disp_text)
    if var:
        try:
            magnitude = int(var.group(1), 16)
        except ValueError:
            return None
        return base, (-magnitude if disp_text.startswith("var") else magnitude)
    value = parse_immediate(disp_text)
    if value is None:
        return None
    return base, (-value if sign == "-" else value)


def _immediate_bytes(value: int, size: Optional[int]) -> Optional[bytes]:
    if size is None:
        magnitude = value if value >= 0 else -value - 1
        size = 1 if magnitude <= 0xFF else 2 if magnitude <= 0xFFFF else 4 if magnitude <= 0xFFFFFFFF else 8
    if size not in (1, 2, 4, 8):
        return None
    limit = 1 << (8 * size)
    if value < 0:
        value += limit
    if not 0 <= value < limit:
        return None
    return value.to_bytes(size, "little")


def _decode_stack_bytes(raw: bytes) -> Optional[Tuple[str, str]]:
    data = raw.rstrip(b"\x00")
    wide = data + b"\x00" if len(data) % 2 else data
    if len(wide) >= 2 * MIN_STACK_STRING_LENGTH and all(wide[i] == 0 for i in range(1, len(wide), 2)):
        chars = bytes(wide[0::2])
        if all(0x20 <= c < 0x7F for c in chars) and len(chars) >= MIN_STACK_STRING_LENGTH:
            return chars.decode("ascii"), "utf-16le"
    if len(data) >= MIN_STACK_STRING_LENGTH and all(0x20 <= c < 0x7F or c in (0x09, 0x0A, 0x0D) for c in data):
        return data.decode("ascii"), "ascii"
    return None


def extract_stack_strings(instructions: Sequence[Instruction]) -> Tuple[StackString, ...]:
    """Recover strings built by runs of ``mov [stack+off], imm`` stores.

    Immediates are decoded little-endian using the operand size prefix, the
    register size (for ``mov reg, imm`` + ``mov [stack], reg`` pairs), or the
    immediate magnitude. Stores are ordered by stack offset when every offset
    parses, otherwise by instruction order. Minimum length is four characters.
    """
    parsed = [parse_instruction(item) for item in tuple(instructions)[:MAX_OUTPUT_ITEMS]]
    results: List[StackString] = []
    run: List[Tuple[int, Optional[int], bytes]] = []
    pending_registers: Dict[str, int] = {}

    def flush() -> None:
        if not run:
            return
        ordered = run
        if all(offset is not None for _, offset, _ in run):
            ordered = sorted(run, key=lambda item: (item[1], item[0]))
        raw = b"".join(chunk for _, _, chunk in ordered)[:MAX_STACK_STRING_BYTES]
        decoded = _decode_stack_bytes(raw)
        if decoded is not None:
            text, encoding = decoded
            results.append(
                StackString(
                    start_address=min(address for address, _, _ in run),
                    end_address=max(address for address, _, _ in run),
                    text=text,
                    encoding=encoding,
                    byte_count=len(raw),
                )
            )
        del run[:]

    for item in parsed:
        if len(results) >= MAX_OUTPUT_ITEMS:
            break
        if item.mnemonic in ("mov", "movabs") and len(item.operands) == 2:
            destination, source = item.operands
            if _is_register(destination):
                immediate = parse_immediate(source)
                if immediate is not None:
                    pending_registers[destination] = immediate
                    continue
                pending_registers.pop(destination, None)
                continue
            located = _stack_offset(destination)
            if located is not None:
                _, size = _strip_size_prefix(destination)
                value = parse_immediate(source)
                if value is None and source in pending_registers:
                    value = pending_registers.pop(source)
                    size = size or _REGISTER_SIZES.get(source)
                if value is not None:
                    chunk = _immediate_bytes(value, size)
                    if chunk is not None:
                        run.append((item.address, located[1], chunk))
                        continue
        if item.mnemonic in ("nop", "lea") or item.mnemonic.startswith("mov") and item.mnemonic != "mov":
            continue
        pending_registers.clear()
        flush()
    flush()
    return tuple(results)


# --------------------------------------------------------------------------- #
# API hashing
# --------------------------------------------------------------------------- #

HASH_ALGORITHMS = ("ror13", "crc32", "djb2", "fnv1a32", "sdbm", "murmur3_32")


def _ror32(value: int, count: int) -> int:
    count &= 31
    return ((value >> count) | (value << (32 - count))) & _MASK32


def _ror13_bytes(data: bytes) -> int:
    result = 0
    for value in data:
        result = (_ror32(result, 13) + value) & _MASK32
    return result


def _djb2(data: bytes) -> int:
    result = 5381
    for value in data:
        result = (result * 33 + value) & _MASK32
    return result


def _fnv1a32(data: bytes) -> int:
    result = 0x811C9DC5
    for value in data:
        result = ((result ^ value) * 0x01000193) & _MASK32
    return result


def _sdbm(data: bytes) -> int:
    result = 0
    for value in data:
        result = (value + (result << 6) + (result << 16) - result) & _MASK32
    return result


def _murmur3_32(data: bytes, seed: int = 0) -> int:
    c1, c2 = 0xCC9E2D51, 0x1B873593
    h = seed & _MASK32
    length = len(data)
    rounded = length - (length % 4)
    for offset in range(0, rounded, 4):
        k = int.from_bytes(data[offset: offset + 4], "little")
        k = (k * c1) & _MASK32
        k = ((k << 15) | (k >> 17)) & _MASK32
        k = (k * c2) & _MASK32
        h ^= k
        h = ((h << 13) | (h >> 19)) & _MASK32
        h = (h * 5 + 0xE6546B64) & _MASK32
    tail = data[rounded:]
    k = 0
    if len(tail) >= 3:
        k ^= tail[2] << 16
    if len(tail) >= 2:
        k ^= tail[1] << 8
    if len(tail) >= 1:
        k ^= tail[0]
        k = (k * c1) & _MASK32
        k = ((k << 15) | (k >> 17)) & _MASK32
        k = (k * c2) & _MASK32
        h ^= k
    h ^= length
    h ^= h >> 16
    h = (h * 0x85EBCA6B) & _MASK32
    h ^= h >> 13
    h = (h * 0xC2B2AE35) & _MASK32
    h ^= h >> 16
    return h


def _check_name(name: str) -> bytes:
    if not isinstance(name, str) or not name or len(name) > 256:
        raise DeobfuscationInputError("name must be 1..256 characters")
    try:
        return name.encode("ascii")
    except UnicodeEncodeError:
        raise DeobfuscationInputError("name must be ASCII")


def hash_name(name: str, algorithm: str) -> int:
    """Hash a bare export name (ASCII, no DLL component) with ``algorithm``.

    For ``ror13`` the input is the function name plus its null terminator, as in
    the classic Metasploit block API hash.
    """
    data = _check_name(name)
    if algorithm == "ror13":
        return _ror13_bytes(data + b"\x00")
    if algorithm == "crc32":
        return zlib.crc32(data) & _MASK32
    if algorithm == "djb2":
        return _djb2(data)
    if algorithm == "fnv1a32":
        return _fnv1a32(data)
    if algorithm == "sdbm":
        return _sdbm(data)
    if algorithm == "murmur3_32":
        return _murmur3_32(data)
    raise DeobfuscationInputError("unknown hash algorithm: {0}".format(algorithm))


def hash_api(dll: str, func: str, algorithm: str) -> int:
    """Hash a ``dll``/``func`` pair.

    ``ror13`` follows Metasploit: ROR-13 over the upper-cased, null-terminated
    UTF-16LE module name, added to ROR-13 over the null-terminated ASCII function
    name. ``hash_api("kernel32.dll", "LoadLibraryA", "ror13") == 0x0726774C``.
    Other algorithms hash only ``func`` (``dll`` is accepted for a uniform API).
    """
    if algorithm != "ror13":
        _check_name(dll)
        return hash_name(func, algorithm)
    module = _check_name(dll).decode("ascii").upper().encode("utf-16le") + b"\x00\x00"
    function = _check_name(func) + b"\x00"
    return (_ror13_bytes(module) + _ror13_bytes(function)) & _MASK32


def _split_candidate(candidate: str) -> Tuple[Optional[str], str]:
    if "!" in candidate:
        dll, func = candidate.split("!", 1)
        return (dll or None), func
    return None, candidate


def resolve_api_hash(hash_value: int, algorithm: str, candidates: Iterable[str]) -> Optional[str]:
    """Return the first candidate whose hash equals ``hash_value``.

    Candidates are ``"dll!Function"`` or bare ``"Function"`` names. For ``ror13``
    a bare name is tried against every DLL in ``known_dll_names()``; a bare name
    also matches when its function-only hash equals the value.
    """
    if not isinstance(hash_value, int) or isinstance(hash_value, bool) or hash_value < 0:
        raise DeobfuscationInputError("hash_value must be a non-negative integer")
    if algorithm not in HASH_ALGORITHMS:
        raise DeobfuscationInputError("unknown hash algorithm: {0}".format(algorithm))
    target = hash_value & _MASK32
    for count, candidate in enumerate(candidates):
        if count >= MAX_CANDIDATES:
            break
        if not isinstance(candidate, str) or not candidate:
            continue
        dll, func = _split_candidate(candidate)
        try:
            if dll is not None:
                if hash_api(dll, func, algorithm) == target:
                    return candidate
                if algorithm != "ror13":
                    continue
            if hash_name(func, algorithm) == target:
                return candidate
            if algorithm == "ror13" and dll is None:
                for module in known_dll_names():
                    if hash_api(module, func, algorithm) == target:
                        return module + "!" + func
        except DeobfuscationInputError:
            continue
    return None


def detect_hash_algorithm(sample_pairs: Iterable[Tuple[str, int]]) -> Optional[str]:
    """Return the algorithm that reproduces every ``(name, hash)`` pair, or ``None``."""
    pairs = []
    for count, pair in enumerate(sample_pairs):
        if count >= 256:
            break
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise DeobfuscationInputError("sample pairs must be (name, hash) tuples")
        pairs.append(pair)
    if not pairs:
        return None
    for algorithm in HASH_ALGORITHMS:
        matched = True
        for name, value in pairs:
            if not isinstance(value, int) or isinstance(value, bool):
                raise DeobfuscationInputError("hash values must be integers")
            dll, func = _split_candidate(name)
            try:
                computed = hash_api(dll, func, algorithm) if dll is not None else hash_name(func, algorithm)
            except DeobfuscationInputError:
                matched = False
                break
            if computed != (value & _MASK32):
                matched = False

