"""IDA adapter for ``analysis/code_signals``: disassembly of author functions and crypto tables.

Read-only, bounded, runs on IDA's thread during Binary Triage. Functions are
scanned in ranking order so the most relevant author code is covered first.
"""

from __future__ import annotations

from typing import Callable, Dict, List, Mapping, Optional, Sequence, Tuple

from ida_ai_malware_analyst_plugin.analysis.code_signals import CRYPTO_TABLES, CodeSignals, build_code_signals
from ida_ai_malware_analyst_plugin.core.context import Instruction
from ida_ai_malware_analyst_plugin.ida.compatibility import IdaModules

_IDA_ERRORS = (AttributeError, RuntimeError, TypeError, ValueError, OverflowError)
_O_MEM = 2
_O_DISPL = 4
MAX_SCAN_FUNCTIONS = 600
MAX_TOTAL_INSTRUCTIONS = 250000
MAX_TABLE_SCAN_BYTES = 48 * 1024 * 1024


def _function_instructions(modules: IdaModules, start: int, limit: int) -> Tuple[List[Instruction], Dict[int, List[int]]]:
    idautils, idc = modules.idautils, modules.idc
    instructions: List[Instruction] = []
    memory: Dict[int, List[int]] = {}
    if idautils is None or idc is None:
        return instructions, memory
    try:
        for count, ea in enumerate(idautils.FuncItems(start)):
            if count >= limit:
                break
            text = idc.GetDisasm(ea) or ""
            instructions.append(Instruction(int(ea), text))
            for index in range(2):
                kind = idc.get_operand_type(ea, index)
                if kind in (_O_MEM, _O_DISPL):
                    value = int(idc.get_operand_value(ea, index))
                    if value > 0x1000:
                        memory.setdefault(int(ea), []).append(value)
    except _IDA_ERRORS:
        pass
    return instructions, memory


def _scan_tables(modules: IdaModules, data_ranges: Sequence[Tuple[int, int]], function_of: Callable[[int], Optional[int]]) -> List[Tuple[int, str, Tuple[int, ...]]]:
    reader = getattr(modules.bytes, "get_bytes", None) if modules.bytes is not None else None
    if not callable(reader) or modules.idautils is None:
        return []
    found: List[Tuple[int, str, Tuple[int, ...]]] = []
    budget = MAX_TABLE_SCAN_BYTES
    for start, end in data_ranges:
        size = min(end - start, budget)
        if size <= 0:
            continue
        budget -= size
        try:
            blob = reader(start, size)
        except _IDA_ERRORS:
            continue
        if not blob:
            continue
        blob = bytes(blob)
        for pattern, label in CRYPTO_TABLES:
            position = blob.find(pattern)
            if position < 0:
                continue
            address = start + position
            referencing: List[int] = []
            try:
                for xref in modules.idautils.XrefsTo(address, 0):
                    function = function_of(int(xref.frm))
                    if function is not None and function not in referencing:
                        referencing.append(function)
            except _IDA_ERRORS:
                pass
            found.append((address, label, tuple(referencing)))
        if budget <= 0:
            break
    return found


def collect_code_signals(
    modules: IdaModules,
    functions: Sequence[Tuple[int, str]],
    data_ranges: Sequence[Tuple[int, int]],
    is_data_address: Callable[[int], bool],
    max_instructions: int = 2000,
) -> CodeSignals:
    """Disassemble the given (author) functions, find crypto tables, build ``CodeSignals``."""
    reader = getattr(modules.bytes, "get_bytes", None) if modules.bytes is not None else None

    def read(address: int, size: int) -> Optional[bytes]:
        if not callable(reader):
            return None
        try:
            value = reader(address, size)
        except _IDA_ERRORS:
            return None
        return bytes(value) if value else None

    def function_of(address: int) -> Optional[int]:
        try:
            function = modules.funcs.get_func(address)
        except _IDA_ERRORS:
            return None
        return int(function.start_ea) if function is not None else None

    batch = []
    total = 0
    for address, name in list(functions)[:MAX_SCAN_FUNCTIONS]:
        instructions, memory = _function_instructions(modules, address, max_instructions)
        total += len(instructions)
        batch.append((address, name, instructions, memory))
        if total >= MAX_TOTAL_INSTRUCTIONS:
            break
    tables = _scan_tables(modules, data_ranges, function_of)
    return build_code_signals(batch, read, is_data_address, tables)

