MAX_SCAN_FUNCTIONS = 600
MAX_TOTAL_INSTRUCTIONS = 250000
MAX_TABLE_SCAN_BYTES = 48 * 1024 * 1024


def _function_instructions(modules: IdaModules, start: int, limit: int) -> Tuple[List[Instruction], Dict[int, List[int]]]:
    idautils, idc = modules.idautils, modules.idc
    instructions: List[Instruction] = []
    memory: Dict[int, List[int]] = {}
    if idautils is None or idc is None:
        return instructions, memory
    try:
        for count, ea in enumerate(idautils.FuncItems(start)):
            if count >= limit:
                break
            text = idc.GetDisasm(ea) or ""
            instructions.append(Instruction(int(ea), text))
            for index in range(2):
                kind = idc.get_operand_type(ea, index)
                if kind in (_O_MEM, _O_DISPL):
                    value = int(idc.get_operand_value(ea, index))
                    if value > 0x1000:
                        memory.setdefault(int(ea), []).append(value)
    except _IDA_ERRORS:
        pass
    return instructions, memory


