from ida_ai_malware_analyst_plugin.core.config import user_config_dir
from ida_ai_malware_analyst_plugin.llm.base import (
    LLMProvider, LLMProviderError, LLMRequest, LLMResponse, ProviderHealth, usage_from,
)

ISSUER = "https://auth.openai.com"
AUTH_URL = ISSUER + "/api/accounts/authorize"
TOKEN_URL = ISSUER + "/api/accounts/oauth/token"
JWKS_URL = ISSUER + "/.well-known/jwks.json"
API_ROOT = "https://api.openai.com/v1"
RESOURCE = API_ROOT
CALLBACK_PATH = "/auth/callback"
APP_NAME = "IDA AI Malware Analyst"
MAX_BODY = 16 * 1024 * 1024
_lock = threading.RLock()


class ChatGPTError(LLMProviderError):
    """Credential-free ChatGPT OAuth or inference error."""


def _safe_error_detail(body: object) -> str:
    """Extract only machine-readable diagnostics; never surface arbitrary response text."""
    if not isinstance(body, dict):
        return ""
    error = body.get("error")
    if not isinstance(error, dict):
        return ""
    parts = []
    for key in ("code", "type"):
        value = error.get(key)
        if isinstance(value, str) and value:
            safe = "".join(ch for ch in value[:80].lower() if ch.isalnum() or ch in "_-")
            if safe and safe not in parts:
                parts.append(safe)
    param = error.get("param")
    if isinstance(param, str) and param:
        safe_param = "".join(ch for ch in param[:80] if ch.isalnum() or ch in "_.[]-")
        if safe_param:
            parts.append("param=" + safe_param)
    return ", ".join(parts)


def _paths() -> Tuple[Path, Path]:
    root = user_config_dir() / "ida_ai_malware_analyst"
    return root / "chatgpt_credentials.dat", root / "chatgpt_host_id"


def _protect(raw: bytes) -> bytes:
    if os.name == "nt":
        class Blob(ctypes.Structure):
            _fields_ = [("cbData", ctypes.c_ulong), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]
        source_buf = ctypes.create_string_buffer(raw)
        source = Blob(len(raw), ctypes.cast(source_buf, ctypes.POINTER(ctypes.c_ubyte)))
        result = Blob()
        crypt = ctypes.windll.crypt32.CryptProtectData
        crypt.argtypes = [ctypes.POINTER(Blob), ctypes.c_wchar_p, ctypes.c_void_p,
                          ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(Blob)]
        crypt.restype = ctypes.c_bool
        if not crypt(ctypes.byref(source), "IDA AI Malware Analyst ChatGPT session", None, None, None, 1, ctypes.byref(result)):
            raise ChatGPTError("Windows credential protection failed")
        try:
            return ctypes.string_at(result.pbData, result.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(result.pbData)
    return raw


def _unprotect(raw: bytes) -> bytes:
    if os.name == "nt":
        class Blob(ctypes.Structure):
            _fields_ = [("cbData", ctypes.c_ulong), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]
        source_buf = ctypes.create_string_buffer(raw)
        source = Blob(len(raw), ctypes.cast(source_buf, ctypes.POINTER(ctypes.c_ubyte)))
        result = Blob()
        crypt = ctypes.windll.crypt32.CryptUnprotectData
        crypt.argtypes = [ctypes.POINTER(Blob), ctypes.POINTER(ctypes.c_wchar_p), ctypes.c_void_p,
                          ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(Blob)]
        crypt.restype = ctypes.c_bool
        if not crypt(ctypes.byref(source), None, None, None, None, 1, ctypes.byref(result)):
            raise ChatGPTError("Saved ChatGPT credentials could not be decrypted; sign in again")
        try:
            return ctypes.string_at(result.pbData, result.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(result.pbData)
    return raw


def _write_private(path: Path, raw: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    fd = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, stat.S_IRUSR | stat.S_IWUSR)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.chmod(str(temporary), stat.S_IRUSR | stat.S_IWUSR)
        except OSError:
            pass
        os.replace(str(temporary), str(path))
    except BaseException:
        try:
            temporary.unlink()
        except OSError:
            pass
        raise


def _load_credentials() -> Optional[dict]:
    path, _ = _paths()
    try:
        value = json.loads(_unprotect(path.read_bytes()).decode("utf-8"))
    except FileNotFoundError:
        return None
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        raise ChatGPTError("Saved ChatGPT credentials are unavailable; sign in again") from exc
    if not isinstance(value, dict) or not all(isinstance(value.get(k), str) and value.get(k) for k in
            ("client_id", "subject")):
        raise ChatGPTError("Saved ChatGPT credentials are incomplete; sign in again")
    return value


def has_credentials() -> bool:
    try:
        record = _load_credentials()
        return bool(record and all(isinstance(record.get(k), str) and record.get(k)
                                   for k in ("access_token", "refresh_token", "id_token")))
    except ChatGPTError:
        return False


def has_saved_account() -> bool:
    """Whether account registration details remain, including after disconnect."""
    try:
        return _load_credentials() is not None
    except ChatGPTError:
        return False


def _save_credentials(value: dict) -> None:
    path, _ = _paths()
    encoded = json.dumps(value, separators=(",", ":")).encode("utf-8")
    _write_private(path, _protect(encoded))


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _decode_part(part: str) -> bytes:
    return base64.urlsafe_b64decode(part + "=" * (-len(part) % 4))


def _http_json(url: str, method: str = "GET", payload: Optional[Mapping[str, object]] = None,
               headers: Optional[Mapping[str, str]] = None, timeout: float = 30.0) -> dict:
    data = None
    request_headers = {"User-Agent": "IDA-AI-Malware-Analyst"}
    if headers:
        request_headers.update(headers)
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        request_headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=request_headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read(MAX_BODY + 1)
    except urllib.error.HTTPError as exc:
        # Surface only a conservative provider error code; never echo token or response text.
        code = None
        try:
            body = json.loads(exc.read(65536).decode("utf-8"))
            error = body.get("error") if isinstance(body, dict) else None
            if isinstance(error, dict):
                code = error.get("code") or error.get("type")
        except Exception:
            pass
        safe = "".join(ch for ch in str(code or "")[:64].lower() if ch.isalnum() or ch in "_-")
        raise ChatGPTError("ChatGPT request failed (HTTP {0}{1})".format(exc.code, ": " + safe if safe else "")) from exc
    except (OSError, TimeoutError) as exc:
        raise ChatGPTError("ChatGPT request failed due to a network or timeout error") from exc
    if len(raw) > MAX_BODY:
        raise ChatGPTError("ChatGPT response exceeded the size limit")
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ChatGPTError("ChatGPT returned invalid JSON") from exc
    if not isinstance(parsed, dict):
        raise ChatGPTError("ChatGPT response was not a JSON object")
    return parsed


def _form_post(url: str, form: Mapping[str, str]) -> dict:
    body = urllib.parse.urlencode(form).encode("ascii")
    request = urllib.request.Request(url, data=body, headers={
        "Content-Type": "application/x-www-form-urlencoded", "User-Agent": "IDA-AI-Malware-Analyst",
    }, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30.0) as response:
            raw = response.read(65537)
    except urllib.error.HTTPError as exc:
        code = "oauth_error"
        try:
            body_json = json.loads(exc.read(65536).decode("utf-8"))
            code = body_json.get("error", code) if isinstance(body_json, dict) else code
        except Exception:
            pass
        safe = "".join(ch for ch in str(code)[:64].lower() if ch.isalnum() or ch in "_-") or "oauth_error"
        raise ChatGPTError("ChatGPT sign-in failed ({0})".format(safe)) from exc
    except (OSError, TimeoutError) as exc:
        raise ChatGPTError("ChatGPT sign-in failed due to a network or timeout error") from exc
    if len(raw) > 65536:
        raise ChatGPTError("ChatGPT token response exceeded the size limit")
    try:
        result = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ChatGPTError("ChatGPT token response was invalid") from exc
    if not isinstance(result, dict):
        raise ChatGPTError("ChatGPT token response was invalid")
    return result


def _verify_id_token(token: str, expected_nonce: str, client_id: str) -> dict:
    pieces = token.split(".")
    if len(pieces) != 3:
        raise ChatGPTError("ChatGPT returned an invalid identity token")
    try:
        header = json.loads(_decode_part(pieces[0]).decode("utf-8"))
        claims = json.loads(_decode_part(pieces[1]).decode("utf-8"))
    except Exception as exc:
        raise ChatGPTError("ChatGPT returned an invalid identity token") from exc
    if not isinstance(header, dict) or header.get("alg") != "RS256" or not isinstance(claims, dict):
        raise ChatGPTError("ChatGPT identity token used an unsupported signature")
    kid = header.get("kid")
    jwks = _http_json(JWKS_URL)
    keys = jwks.get("keys")
    key = next((item for item in keys if isinstance(item, dict) and item.get("kid") == kid
                and item.get("kty") == "RSA" and item.get("alg", "RS256") == "RS256"
                and item.get("use", "sig") == "sig"), None) if isinstance(keys, list) else None
    if key is None:
        raise ChatGPTError("ChatGPT identity signing key was not found")
    try:
        modulus = int.from_bytes(_decode_part(key["n"]), "big")
        exponent = int.from_bytes(_decode_part(key["e"]), "big")
        signature = _decode_part(pieces[2])
        signed = (pieces[0] + "." + pieces[1]).encode("ascii")
        digest_info = bytes.fromhex("3031300d060960864801650304020105000420") + hashlib.sha256(signed).digest()
        width = (modulus.bit_length() + 7) // 8
        if len(signature) != width:
            raise ValueError("signature length")
        decoded = pow(int.from_bytes(signature, "big"), exponent, modulus).to_bytes(width, "big")
        padding = width - len(digest_info) - 3
        expected = b"\x00\x01" + b"\xff" * padding + b"\x00" + digest_info
        if padding < 8 or not secrets.compare_digest(decoded, expected):
            raise ValueError("signature")
    except Exception as exc:
        raise ChatGPTError("ChatGPT identity token signature could not be verified") from exc
    now = int(time.time())
    audience = claims.get("aud")
    if (claims.get("iss") != ISSUER or client_id not in (audience if isinstance(audience, list) else [audience])
            or not isinstance(claims.get("exp"), int) or isinstance(claims.get("exp"), bool) or claims["exp"] <= now - 5
            or not isinstance(claims.get("iat"), int) or isinstance(claims.get("iat"), bool) or claims["iat"] > now + 5
            or not isinstance(claims.get("sub"), str) or not claims["sub"]
            or claims.get("nonce") != expected_nonce):
        raise ChatGPTError("ChatGPT identity token validation failed")
    return claims


def sign_in() -> str:
    """Open the system browser, complete OAuth on loopback, verify and persist the grant."""
    with _lock:
        _, host_path = _paths()
        if host_path.exists():
            host_id = host_path.read_text(encoding="ascii").strip()
        else:
            host_id = "urn:uuid:" + str(uuid.uuid4())
            _write_private(host_path, host_id.encode("ascii"))
        existing = _load_credentials()
        client_id = existing.get("client_id") if existing else "dynamic_agent_client"
        state, nonce, verifier = secrets.token_urlsafe(32), secrets.token_urlsafe(32), secrets.token_urlsafe(48)
        challenge = _b64url(hashlib.sha256(verifier.encode("ascii")).digest())
        captured = {}
        ready = threading.Event()
        stop_server = threading.Event()

        class Handler(http.server.BaseHTTPRequestHandler):
            def do_GET(self):  # noqa: N802
                parsed = urllib.parse.urlsplit(self.path)
                if parsed.path != CALLBACK_PATH:
                    self.send_error(404)
                    return
                captured.update({k: v[0] for k, v in urllib.parse.parse_qs(parsed.query).items() if v})
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(b"<!doctype html><title>IDA AI Malware Analyst</title><p>Sign-in complete. Return to IDA Pro.</p>")
                ready.set()
            def log_message(self, *_args):
                return

        try:
            server = http.server.HTTPServer(("127.0.0.1", 1455), Handler)
        except OSError:
            # The documented loopback flow permits another port when 1455 is busy.
            server = http.server.HTTPServer(("127.0.0.1", 0), Handler)
        server.timeout = 1.0
        redirect_uri = "http://127.0.0.1:{0}{1}".format(server.server_port, CALLBACK_PATH)
        params = {
            "client_id": client_id, "response_type": "code", "redirect_uri": redirect_uri,
            "scope": "openid profile email offline_access resource.invoke chatgpt.tokens.use.direct",
            "resource": RESOURCE, "state": state, "nonce": nonce,
            "code_challenge_method": "S256", "code_challenge": challenge,
            "ext_agent_host_id": host_id,
        }
        if client_id == "dynamic_agent_client":
            params["agent_name_hint"] = APP_NAME
        elif existing:
            if existing.get("id_token"):
                params["id_token_hint"] = existing["id_token"]
            if existing.get("email"):
                params["login_hint"] = existing["email"]
        thread = threading.Thread(target=lambda: _serve_callback(server, ready, stop_server), daemon=True)
        thread.start()
        try:
            if not webbrowser.open(AUTH_URL + "?" + urllib.parse.urlencode(params)):
                raise ChatGPTError("Could not open the system browser for ChatGPT sign-in")
            if not ready.wait(300):
                raise ChatGPTError("ChatGPT sign-in timed out")
        finally:
            stop_server.set()
            server.server_close()
        if not secrets.compare_digest(captured.get("state", ""), state):
            raise ChatGPTError("ChatGPT sign-in state validation failed")
        if captured.get("error"):
            raise ChatGPTError("ChatGPT sign-in was declined or failed")
        code = captured.get("code")
        issued_client = captured.get("client_id") or client_id
        if not code or issued_client == "dynamic_agent_client":
            raise ChatGPTError("ChatGPT did not complete client registration")
        if existing and issued_client != existing["client_id"]:
            raise ChatGPTError("ChatGPT returned a different registered client")
        tokens = _form_post(TOKEN_URL, {
            "grant_type": "authorization_code", "client_id": issued_client, "code": code,
            "code_verifier": verifier, "redirect_uri": redirect_uri, "resource": RESOURCE,
        })
        scopes = set(str(tokens.get("scope", "")).split())
        if "chatgpt.tokens.use.direct" not in scopes:
            raise ChatGPTError("ChatGPT plan usage permission was not granted")
        id_token = tokens.get("id_token")
        access_token, refresh_token = tokens.get("access_token"), tokens.get("refresh_token")
        if not all(isinstance(x, str) and x for x in (id_token, access_token, refresh_token)):
            raise ChatGPTError("ChatGPT token response was incomplete")
        claims = _verify_id_token(id_token, nonce, issued_client)
        if existing and existing.get("subject") != claims["sub"]:
            raise ChatGPTError("The signed-in ChatGPT account differs from the saved account; disconnect it first")
        email = claims.get("email") if isinstance(claims.get("email"), str) else None
        record = {
            "client_id": issued_client, "subject": claims["sub"], "email": email,
            "id_token": id_token, "access_token": access_token, "refresh_token": refresh_token,
            "scopes": sorted(scopes), "expires_at": int(time.time()) + int(tokens.get("expires_in", 3600)),
        }
        _save_credentials(record)
        return "Signed in with ChatGPT" + (" as " + record["email"] if record.get("email") else "")


def _serve_callback(server: http.server.HTTPServer, ready: threading.Event, stop: threading.Event) -> None:
    while not ready.is_set() and not stop.is_set():
        try:
            server.handle_request()
        except OSError:
            return


def sign_out() -> str:
    """Revoke the renewable session when possible, then remove local credentials."""
    path, _ = _paths()
    remote_confirmed = False
    try:
        record = _load_credentials()
        if record:
            if record.get("refresh_token"):
                discovery = _http_json(ISSUER + "/.well-known/openid-configuration")
                revoke_url = discovery.get("revocation_endpoint")
                parsed_revoke = urlsplit(revoke_url) if isinstance(revoke_url, str) else None
                if parsed_revoke is None or parsed_revoke.scheme != "https" or parsed_revoke.hostname != "auth.openai.com":
                    raise ChatGPTError("ChatGPT revocation endpoint could not be verified")
                revoke_body = urllib.parse.urlencode({
                        "token": record["refresh_token"], "token_type_hint": "refresh_token",
                        "client_id": record["client_id"],
                    }).encode("ascii")
                revoke_headers = {
                        "Content-Type": "application/x-www-form-urlencoded", "User-Agent": "IDA-AI-Malware-Analyst",
                    }
                for attempt in range(3):
                    request = urllib.request.Request(revoke_url, data=revoke_body, method="POST", headers=revoke_headers)
                    try:
                        with urllib.request.urlopen(request, timeout=8.0) as response:
                            remote_confirmed = response.status == 200
                    except urllib.error.HTTPError as exc:
                        remote_confirmed = exc.code == 200
                        if exc.code < 500:
                            break
                    except (urllib.error.URLError, OSError, TimeoutError):
                        remote_confirmed = False
                    if remote_confirmed or attempt == 2:
                        break
                    time.sleep(0.5 * (2 ** attempt))
    except (ChatGPTError, OSError, ValueError):
        pass
    try:
        record = _load_credentials()
        if record:
            for field in ("access_token", "refresh_token", "id_token", "expires_at", "scopes"):
                record.pop(field, None)
            _save_credentials(record)
        else:
            path.unlink()
    except FileNotFoundError:
        pass
    return ("ChatGPT session disconnected" if remote_confirmed else
            "ChatGPT credentials removed locally; remote revocation was not confirmed")


def forget_account() -> str:
    """Disconnect and remove the registration too, allowing a different ChatGPT account."""
    status = sign_out()
    path, _ = _paths()
    try:
        path.unlink()
    except FileNotFoundError:
        pass
    return status + "; saved account forgotten"


class ChatGPTProvider(LLMProvider):
    def __init__(self, model: str, timeout_seconds: float = 120.0) -> None:
        self._model = model
        self._timeout = timeout_seconds

    def _access_token(self) -> str:
        with _lock:
            record = _load_credentials()
            if not record or not has_credentials():
                raise ChatGPTError("Sign in with ChatGPT in Settings to use your ChatGPT plan")
            if int(record.get("expires_at", 0)) > int(time.time()) + 60:
                return record["access_token"]
            refreshed = _form_post(TOKEN_URL, {
                "grant_type": "refresh_token", "client_id": record["client_id"],
                "refresh_token": record["refresh_token"], "resource": RESOURCE,
            })
            if not all(isinstance(refreshed.get(k), str) and refreshed[k] for k in ("access_token", "refresh_token")):
                raise ChatGPTError("ChatGPT token refresh was incomplete; sign in again")
            record.update(access_token=refreshed["access_token"], refresh_token=refreshed["refresh_token"],
                          expires_at=int(time.time()) + int(refreshed.get("expires_in", 3600)))
            _save_credentials(record)
            return record["access_token"]

    def list_models(self) -> Tuple[str, ...]:
        payload = _http_json(API_ROOT + "/models", headers={"Authorization": "Bearer " + self._access_token()})
        models = payload.get("models")
        if not isinstance(models, list):
            raise ChatGPTError("ChatGPT model response was invalid")
        return tuple(item["slug"] for item in models if isinstance(item, dict)
                     and item.get("visibility") == "list" and isinstance(item.get("slug"), str))[:100]

    def generate(self, request: LLMRequest) -> LLMResponse:
        token = self._access_token()
        payload = {
            "model": self._model,
            "input": [{"role": "user", "content": request.prompt}],
            "store": False,
            "stream": True,
        }
        if request.system_instruction:
            payload["instructions"] = request.system_instruction
        body = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(API_ROOT + "/responses", data=body, method="POST", headers={
            "Authorization": "Bearer " + token, "Content-Type": "application/json",
            "Accept": "text/event-stream", "User-Agent": "IDA-AI-Malware-Analyst",
        })
        chunks = []
        usage = None
        completed = False
        try:
            with urllib.request.urlopen(req, timeout=self._timeout) as response:
                total = 0
                for raw_line in response:
                    total += len(raw_line)
                    if total > MAX_BODY:
                        raise ChatGPTError("ChatGPT stream exceeded the size limit")
                    line = raw_line.decode("utf-8", "replace").strip()
                    if not line.startswith("data:"):
                        continue
                    data = line[5:].strip()
                    if data == "[DONE]":
                        break
                    try:
                        event = json.loads(data)
                    except json.JSONDecodeError:
                        continue
                    if not isinstance(event, dict):
                        continue
                    kind = event.get("type")
                    if kind == "response.output_text.delta" and isinstance(event.get("delta"), str):
                        chunks.append(event["delta"])
                    elif kind == "response.incomplete":
                        result = event.get("response")
                        details = result.get("incomplete_details") if isinstance(result, dict) else None
                        reason = details.get("reason") if isinstance(details, dict) else None
                        safe_reason = "".join(ch for ch in str(reason or "")[:64].lower() if ch.isalnum() or ch in "_-")
                        raise ChatGPTError("ChatGPT response was incomplete" + (" (" + safe_reason + ")" if safe_reason else ""))
                    elif kind == "response.completed":
                        completed = True
                        result = event.get("response")
                        if isinstance(result, dict):
                            usage = usage_from(result.get("usage"), "input_tokens", "output_tokens")
                    elif kind in ("response.failed", "error"):
                        result = event.get("response")
                        error = result.get("error") if isinstance(result, dict) else event.get("error")
                        safe = _safe_error_detail({"error": error} if isinstance(error, dict) else {})
                        raise ChatGPTError("ChatGPT response failed ({0})".format(safe or "request_failed"))
        except urllib.error.HTTPError as exc:
            try:
                response_body = json.loads(exc.read(65536).decode("utf-8"))
            except Exception:
                response_body = None
            detail = _safe_error_detail(response_body)
            request_id = exc.headers.get("x-request-id", "") if exc.headers else ""
            safe_request_id = "".join(ch for ch in request_id[:96] if ch.isalnum() or ch in "_-")
            suffix = (": " + detail if detail else "") + ("; request id " + safe_request_id if safe_request_id else "")
            raise ChatGPTError("ChatGPT Responses request failed (HTTP {0}{1})".format(exc.code, suffix)) from exc
        except (OSError, TimeoutError) as exc:
            raise ChatGPTError("ChatGPT Responses request failed due to a network or timeout error") from exc
        if not completed:
            raise ChatGPTError("ChatGPT response ended before completion")
        text = "".join(chunks).strip()
        if not text:
            raise ChatGPTError("ChatGPT returned an empty answer")
        return LLMResponse(text=text, model=self._model, usage=usage)

    def health_check(self) -> ProviderHealth:
        try:
            models = self.list_models()
            if self._model not in models:
                return ProviderHealth(
                    available=False,
                    model=self._model,
                    detail="Selected model is not available to this ChatGPT account; fetch models and choose an available model",
                )
            return ProviderHealth(available=True, model=self._model)
        except LLMProviderError as exc:
            return ProviderHealth(available=False, model=self._model, detail=str(exc))

