"""The single place that turns a ``PluginConfig`` into a concrete ``LLMProvider``."""

from __future__ import annotations

from ida_ai_malware_analyst_plugin.core.config import ConfigurationError, PluginConfig
from ida_ai_malware_analyst_plugin.llm.base import LLMProvider
from ida_ai_malware_analyst_plugin.llm.claude import ClaudeProvider, ClaudeSettings
from ida_ai_malware_analyst_plugin.llm.gemini import GeminiProvider, GeminiSettings
from ida_ai_malware_analyst_plugin.llm.openai_compat import OpenAICompatProvider, OpenAICompatSettings
from ida_ai_malware_analyst_plugin.llm.chatgpt import ChatGPTProvider


def build_provider(config: PluginConfig) -> LLMProvider:
    """Return the provider selected by ``config.provider``; no network activity happens here."""
    if config.provider == "gemini":
        return GeminiProvider(GeminiSettings.from_plugin_config(config))
    if config.provider == "claude":
        return ClaudeProvider(ClaudeSettings.from_plugin_config(config))
    if config.provider == "openai":
        return OpenAICompatProvider(OpenAICompatSettings.from_plugin_config(config))
    if config.provider == "chatgpt":
        return ChatGPTProvider(config.chatgpt_model, timeout_seconds=config.gemini_timeout_seconds)
    raise ConfigurationError("Unsupported provider: {0}".format(config.provider))

def _resolve_provider(value: Any) -> Tuple[str, Optional[str]]:
    """Return ``(provider id, alias used or None)``; aliases such as ``radox`` map to ``openai``."""
    if not isinstance(value, str):
        raise ConfigurationError("provider must be one of: " + ", ".join(sorted(PROVIDERS) + sorted(PROVIDER_ALIASES)))
    normalized = value.strip().lower()
    if normalized in PROVIDER_ALIASES:
        return PROVIDER_ALIASES[normalized], normalized
    if normalized not in PROVIDERS:
        raise ConfigurationError("provider must be one of: " + ", ".join(sorted(PROVIDERS) + sorted(PROVIDER_ALIASES)))
    return normalized, None


def validate_base_url(value: Any) -> str:
    """Normalise an OpenAI-compatible base URL or raise ``ValueError``.

    ``https://`` is required, except that ``http://`` is tolerated for loopback
    hosts so local servers (Ollama, vLLM) work. Query strings, fragments and
    credentials in the URL are rejected; a trailing slash is removed so paths
    such as ``/chat/completions`` can be appended uniformly.
    """
    if not isinstance(value, str) or not value.strip():
        raise ValueError("base_url must be a non-empty string")
    candidate = value.strip()
    parts = urlsplit(candidate)
    if parts.scheme not in ("https", "http"):
        raise ValueError("base_url must start with https://")
    if not parts.hostname:
        raise ValueError("base_url must contain a host")
    if parts.scheme == "http" and parts.hostname.lower() not in _LOOPBACK_HOSTS:
        raise ValueError("base_url must use https:// (http:// is only allowed for localhost / 127.0.0.1)")
    if parts.query or parts.fragment or candidate.endswith("?") or candidate.endswith("#"):
        raise ValueError("base_url must not contain a query string or fragment")
    if parts.username is not None or parts.password is not None:
        raise ValueError("base_url must not embed credentials")
    if any(char.isspace() for char in candidate):
        raise ValueError("base_url must not contain whitespace")
    return candidate.rstrip("/")


# Known OpenAI-compatible services, keyed by host, with the label shown in notices.
KNOWN_OPENAI_COMPATIBLE_HOSTS: Dict[str, str] = {
    "radoxai.com": "Radox AI",
    "freemodel.in": "FreeModel",
    "api.openai.com": "OpenAI",
    "openrouter.ai": "OpenRouter",
    "api.groq.com": "Groq",
}


def _base_url_host(value: str) -> str:
    try:
        host = urlsplit(value).hostname
    except ValueError:
        return ""
    return (host or "").lower()


def known_service_label(value: str) -> Optional[str]:
    """Label for a recognised OpenAI-compatible host (or subdomain), else ``None``."""
    host = _base_url_host(value)
    if not host:
        return None
    for known, label in KNOWN_OPENAI_COMPATIBLE_HOSTS.items():
        if host == known or host.endswith("." + known):
            return label
    return None


def is_radox_base_url(value: str) -> bool:
    """True when the base URL points at Radox AI (``radoxai.com`` or a subdomain)."""
    return known_service_label(value) == "Radox AI"


def _validate_config_base_url(value: Any) -> str:
    try:
        return validate_base_url(value)
    except ValueError as exc:
        raise ConfigurationError("openai_base_url: {0}".format(exc)) from exc


def _environment_key(name: str) -> Optional[str]:
    value = os.environ.get(name)
    if value is None:
        return None
    if not value.strip():
        raise ConfigurationError("{0} must not be empty when set".format(name))
    return value.strip()


def user_config_dir() -> Path:
    """Per-user directory IDA itself uses for user files (``IDAUSR`` honoured).

    Windows: ``%APPDATA%\\Hex-Rays\\IDA Pro``; elsewhere ``~/.idapro``. This is
    always writable by the user, unlike a plugin folder under Program Files.
    """
    idausr = os.environ.get("IDAUSR")
    if idausr:
        # IDAUSR may hold several directories; the first is the user's own.
        first = idausr.split(os.pathsep)[0].strip()
        if first:
            return Path(first)
    appdata = os.environ.get("APPDATA")
    if os.name == "nt" and appdata:
        return Path(appdata) / "Hex-Rays" / "IDA Pro"
    return Path.home() / ".idapro"


def _directory_writable(directory: Path) -> bool:
    try:
        directory.mkdir(parents=True, exist_ok=True)
        probe = directory / (".write-test-" + str(os.getpid()))
        with probe.open("w", encoding="utf-8") as handle:
            handle.write("")
        probe.unlink()
        return True
    except OSError:
        return False


def config_path_for(plugin_root: Path) -> Path:
    """The configuration file the plugin reads and the Settings dialog writes.

    Resolution order: a file already present beside the plugin; otherwise a file
    already present in the per-user IDA directory; otherwise the plugin folder if
    it is writable (portable installs), else the per-user directory (installs
    under Program Files, where writes need administrator rights).
    """
    beside_plugin = Path(plugin_root) / CONFIG_FILE_NAME
    if beside_plugin.is_file():
        return beside_plugin
    per_user = user_config_dir() / CONFIG_FILE_NAME
    if per_user.is_file():
        return per_user
    if _directory_writable(Path(plugin_root)):
        return beside_plugin
    return per_user


def load_file_config(path: Optional[Path]) -> PluginConfig:
    """Load only the JSON file (no environment overrides); a missing file yields the defaults."""
    if path is None or not path.is_file():
        return PluginConfig()
    try:
        with path.open("r", encoding="utf-8") as config_file:
            raw = json.load(config_file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ConfigurationError("Could not read configuration file: {0}".format(path)) from exc
    if not isinstance(raw, dict):
        raise ConfigurationError("Configuration root must be a JSON object")
    return PluginConfig.from_mapping(raw)


def save_config(config: PluginConfig, path: Path, include_secrets: bool = True) -> Path:
    """Write ``config`` as pretty JSON, atomically, readable only by the current user where possible.

    The parent directory is created when missing. The content is written to a
    temporary file beside ``path`` and moved into place with ``os.replace`` so
    a crash never leaves a truncated configuration. On POSIX the file is
    created with mode ``0o600``; the permission change is best effort (Windows
    ACLs are not touched). Raises ``OSError`` when the file cannot be written.
    """
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(config.to_mapping(include_secrets=include_secrets), indent=2) + "\n"
    temporary = target.with_name(target.name + ".tmp")
    descriptor = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, stat.S_IRUSR | stat.S_IWUSR)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.chmod(str(temporary), stat.S_IRUSR | stat.S_IWUSR)
        except OSError:
            pass
        os.replace(str(temporary), str(target))
    except BaseException:
        try:
            os.unlink(str(temporary))
        except OSError:
            pass
        raise
    return target


def env_overrides_active() -> Dict[str, str]:
    """Environment variables currently set that override file values: ``{name: field}``.

    Only names are returned, never values, so the result is safe to show in
    the Settings dialog ("GEMINI_API_KEY is set and overrides the saved key").
    """
    return {name: field_name for name, field_name in ENV_OVERRIDE_FIELDS.items() if os.environ.get(name) is not None}


def load_config(path: Optional[Path] = None) -> PluginConfig:
    """Load an optional JSON config file, falling back to safe defaults.

    A missing file is not an error so a copied plugin folder works immediately.
    Only the explicit ``path`` is consulted; there is no environment override
    for the file location. The only environment inputs are the provider
    selector ``IDA_AI_PROVIDER``, the key variables ``GEMINI_API_KEY``,
    ``ANTHROPIC_API_KEY`` and ``OPENAI_API_KEY``, the OpenAI-compatible base
    URL ``IDA_AI_BASE_URL`` and the generic model override ``IDA_AI_MODEL``
    (applies to whichever provider is active), each overriding the matching
    file value. Values saved from the Settings dialog therefore stay in the
    file but are shadowed while the variable is set; ``env_overrides_active``
    reports which ones.
    """
    loaded = load_file_config(path)

    overrides = {}
    environment_provider = os.environ.get(PROVIDER_ENV_VAR)
    if environment_provider is not None:
        provider, alias = _resolve_provider(environment_provider)
        overrides["provider"] = provider
        if alias in ALIAS_BASE_URLS:
            overrides["openai_base_url"] = ALIAS_BASE_URLS[alias]
    gemini_key = _environment_key(GEMINI_API_KEY_ENV_VAR)
    if gemini_key is not None:
        overrides["gemini_api_key"] = gemini_key
    claude_key = _environment_key(ANTHROPIC_API_KEY_ENV_VAR)
    if claude_key is not None:
        overrides["claude_api_key"] = claude_key
    openai_key = _environment_key(OPENAI_API_KEY_ENV_VAR)
    if openai_key is not None:
        overrides["openai_api_key"] = openai_key
    base_url = _environment_key(BASE_URL_ENV_VAR)
    if base_url is not None:
        overrides["openai_base_url"] = _validate_config_base_url(base_url)
    model = _environment_key(MODEL_ENV_VAR)
    if model is not None:
        active = overrides.get("provider", loaded.provider)
        overrides[MODEL_FIELD_BY_PROVIDER[active]] = model
    return replace(loaded, **overrides) if overrides else loaded

        is_running=self.is_running,
        changes=ChangeActions(
            list_changes=self.listed_changes,
            audit_entries=self.audit_entries,
            approve=self.approve_change,
            reject=self.reject_change,
            rollback=self.rollback_change,
            propose=lambda operation, address, value: self.propose_change(operation, address, value, source="analyst"),
        ),
        history_text=self.history_text,
        jump_to=self.jump_to,
        clear_cache=self.clear_cache,
        settings=self.settings_actions(),
        propose_decoded_comments=self.propose_decoded_comments,
        sweep_size=lambda: self._config.sweep_max_functions,
        token_usage=self.token_usage_text,
    )

def settings_actions(self) -> SettingsActions:
    """The callable bundle behind the Settings dialog; it never receives the config object."""
    return SettingsActions(
        current=self.current_settings,
        fetch_models=self.fetch_models,
        test_connection=self.test_connection,
        save=self.save_settings,
        sign_in=self.sign_in_chatgpt,
        sign_out=self.sign_out_chatgpt,
        forget_account=self.forget_chatgpt_account,
    )

def external_ai_notice(self) -> Optional[str]:
    if not self._config.show_external_ai_notice:
        return None
    return "External AI: {0} ({1})".format(self._config.provider_label, self._config.active_model)

# -- settings (Settings dialog) -------------------------------------------

def config_path(self) -> Path:
    return config_path_for(self._plugin_root)

def current_settings(self) -> Dict[str, Any]:
    """Active settings for the dialog: every non-secret field, ``has_key`` flags, env override names."""
    values = self._config.to_mapping(include_secrets=False)
    values["has_key"] = {provider: self._config.has_key(provider) for provider in PROVIDERS}
    from ida_ai_malware_analyst_plugin.llm.chatgpt import has_saved_account
    values["has_chatgpt_account"] = has_saved_account()
    values["env_overrides"] = env_overrides_active()
    values["config_path"] = str(self.config_path())
    values["provider_label"] = self._config.provider_label
    return values

def _settings_busy_status(self) -> Optional[str]:
    if self._running_kind is not None:
        return "Busy: {0} running".format(self._running_kind)
    if self._settings_request is not None:
        return "Busy: {0} running".format(self._settings_request)
    return None

def _candidate_config(self, settings: Mapping[str, Any]) -> PluginConfig:
    """Validate dialog values against the active config (``save_key_to_file`` is not a config key)."""
    updates = {name: value for name, value in settings.items() if name != "save_key_to_file"}
    return self._config.with_updates(**updates)

def list_models_for(self, provider: str, base_url: str, api_key: Optional[str]) -> Tuple[str, ...]:
    """Synchronous model listing for ``provider``; a blank key falls back to the configured one."""
    updates: Dict[str, Any] = {"provider": provider}
    if provider in ("openai", "radox") and isinstance(base_url, str) and base_url.strip():
        updates["openai_base_url"] = base_url.strip()
    candidate = self._config.with_updates(**updates)
    if candidate.provider != "chatgpt" and isinstance(api_key, str) and api_key.strip():
        candidate = candidate.with_updates(**{KEY_FIELD_BY_PROVIDER[candidate.provider]: api_key.strip()})
    return tuple(self._settings_provider_factory(candidate).list_models())

def check_connection(self, settings: Mapping[str, Any]) -> str:
    """Synchronous health check of a temporary provider built from ``settings``; safe text only."""
    candidate = self._candidate_config(settings)
    health = self._settings_provider_factory(candidate).health_check()
    return format_connection_result(candidate.provider_label, health.model, None if health.available else health.detail or "unavailable")

def fetch_models(
    self,
    provider: str,
    base_url: str,
    api_key: Optional[str],
    on_models: Callable[[Tuple[str, ...]], None],
    on_error: Callable[[str], None],
) -> str:
    """Start listing models on a worker; results reach ``on_models`` on the UI thread."""
    return self._start_settings_request(
        "fetch_models", lambda: self.list_models_for(provider, base_url, api_key), on_models, on_error, SETTINGS_FETCHING_STATUS
    )

def test_connection(self, settings: Mapping[str, Any], on_result: Callable[[str], None], on_error: Callable[[str], None]) -> str:
    """Start a health check on a worker; the status text reaches ``on_result`` on the UI thread."""
    return self._start_settings_request(
        "test_connection", lambda: self.check_connection(settings), on_result, on_error, SETTINGS_TESTING_STATUS
    )

def _start_settings_request(
    self,
    name: str,
    work: Callable[[], Any],
    on_success: Callable[[Any], None],
    on_error: Callable[[str], None],
    started_status: str,
) -> str:
    busy = self._settings_busy_status()
    if busy is not None:
        return busy

    def safe_work() -> Any:
        # Provider and validation errors already carry credential-free text; anything
        # else is reduced to its type name so no unexpected message reaches the dialog.
        try:
            return work()
        except (LLMProviderError, ValueError) as exc:
            raise RuntimeError(str(exc)) from exc
        except Exception as exc:
            raise RuntimeError("{0} failed: {1}".format(name, type(exc).__name__)) from exc

    self._settings_request = name
    task = BackgroundTask(
        work=safe_work,
        deliver=self._deliver_on_ida_thread,
        success=lambda result: self._settings_request_done(name, None, result, on_success, on_error),
        failure=lambda message: self._settings_request_done(name, message, None, on_success, on_error),
    )
    self._settings_task = task
    try:
        task.start()
    except Exception as exc:
        self._settings_task = None
        self._settings_request = None
        return "Settings request failed: {0}".format(type(exc).__name__)
    return started_status

def _settings_request_done(
    self, name: str, error: Optional[str], result: Any, on_success: Callable[[Any], None], on_error: Callable[[str], None]
) -> None:
    self._settings_task = None
    self._settings_request = None
    if error is not None:
        log_event(self._logger, "settings_request", request=name, success=False, error=_log_value(error))
        on_error(error)
        return
    log_event(self._logger, "settings_request", request=name, success=True)
    on_success(result)

def save_settings(self, settings: Mapping[str, Any]) -> str:
    """Validate, write the configuration file beside the plugin and apply the settings.

    ``settings`` holds configuration keys from the dialog plus
    ``save_key_to_file``. The runtime config always receives the typed key;
    the file receives it only when ``save_key_to_file`` is true. The file is
    rebuilt from its own current content (not from the runtime config) so
    keys supplied by environment variables are never copied into it.
    Returns the status line to show; nothing is raised.
    """
    save_key = bool(settings.get("save_key_to_file", True))
    try:
        runtime = self._candidate_config(settings)
    except ConfigurationError as exc:
        return "Invalid settings: {0}".format(exc)
    path = self.config_path()
    try:
        file_config = load_file_config(path)
    except ConfigurationError:
        # An unreadable or invalid file is replaced rather than left blocking the save.
        file_config = PluginConfig()
    file_updates = {name: value for name, value in settings.items() if name != "save_key_to_file"}
    typed_key_fields = [name for name in file_updates if name in SECRET_FIELDS]
    if not save_key:
        # Session-only key: keep it out of the file (and drop any earlier saved one for that provider).
        for name in typed_key_fields:
            file_updates[name] = None
        if runtime.provider != "chatgpt":
            file_updates[KEY_FIELD_BY_PROVIDER[runtime.provider]] = None
    try:
        file_candidate = file_config.with_updates(**file_updates)
    except ConfigurationError as exc:
        return "Invalid settings: {0}".format(exc)
    try:
        save_config(file_candidate, path, include_secrets=True)
    except OSError as exc:
        # The file is a convenience; the settings still take effect for this IDA session.
        self._config = runtime
        self._notice_changed()
        log_event(self._logger, "settings_save_failed", error=type(exc).__name__, path=str(path))
        return "Applied for this session, but could not write {0} ({1}). Check folder permissions.".format(
            path, type(exc).__name__
        )
    self._config = runtime
    log_event(
        self._logger,
        "settings_saved",
        provider=runtime.provider,
        model=_log_value(runtime.active_model),
        key_in_file=file_candidate.has_key(runtime.provider),
    )
    self._notice_changed()
    if typed_key_fields and not save_key:
        return SETTINGS_SAVED_STATUS + " (key kept for this IDA session only)"
    return SETTINGS_SAVED_STATUS

def _notice_changed(self) -> None:
    if self._panel is not None:
        try:
            self._panel.set_notice(self.external_ai_notice())
        except Exception:
            pass

def _panel_closed(self) -> None:
    self._panel = None

def shutdown(self) -> None:
    self._unregister_action()
    panel, self._panel = self._panel, None
    if panel is not None:
        panel.close()
    self.cancel_action()
    # Session-scoped storage: nothing about this file outlives the IDA session.
    self._discard_store()
    self._cache.invalidate()
    self._investigations.clear()
    self._last_triage = None

"""Claude (Anthropic Messages API) REST adapter using only the Python standard library.

JSON mode
---------
The Messages API has no response MIME type. When a request asks for
``application/json`` the adapter does two things: it appends an instruction to
the system text asking for a single JSON object and it *prefills* the
assistant turn with ``{`` so the reply has to continue the object. Anthropic
returns only the continuation, so the adapter prepends ``{`` to the returned
text before handing it to the parsers (which already strip Markdown fences and
parse strictly). The prefill is removed from the request when the model is
asked for prose.
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Callable, List, Mapping, Optional, Tuple
from urllib.error import HTTPError
from urllib.request import urlopen

from ida_ai_malware_analyst_plugin.core.config import DEFAULT_CLAUDE_MODEL, PluginConfig
from ida_ai_malware_analyst_plugin.llm.base import (
    LLMProvider,
    LLMProviderError,
    LLMRequest,
    LLMResponse,
    usage_from,
    MissingApiKeyError,
    ProviderHealth,
)
from ida_ai_malware_analyst_plugin.llm.http import (  # noqa: F401 - MAX_RESPONSE_BYTES is re-exported
    MAX_LISTED_MODELS,
    MAX_RESPONSE_BYTES,
    USER_AGENT,
    JsonHttpClient,
    read_error_body_json,
)


CLAUDE_API_BASE_URL = "https://api.anthropic.com/v1"
ANTHROPIC_VERSION = "2023-06-01"
# 529 is Anthropic's "overloaded" status; it is transient like 503.
RETRYABLE_STATUS_CODES = frozenset((429, 500, 502, 503, 504, 529))
MODEL_NAME_CHARSET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"
JSON_MODE_INSTRUCTION = "Respond with a single JSON object only — no prose, no Markdown fences."
JSON_PREFILL = "{"
# Only the machine-readable error type is surfaced; it is restricted to this
# charset and length so a response body can never smuggle text into status lines.
_ERROR_TYPE_CHARSET = "abcdefghijklmnopqrstuvwxyz_"
_ERROR_TYPE_MAX_CHARS = 64


class ClaudeRequestError(LLMProviderError):
    """A request failed after retrying safely retryable transport failures."""


class ClaudeResponseError(LLMProviderError):
    """Claude returned a response that cannot be normalized safely."""


@dataclass(frozen=True)
class ClaudeSettings:
    api_key: Optional[str] = field(default=None, repr=False)
    model: str = DEFAULT_CLAUDE_MODEL
    timeout_seconds: float = 30.0
    max_retries: int = 2
    retry_delay_seconds: float = 1.0
    max_tokens_default: int = 2048

    def __post_init__(self) -> None:
        if self.api_key is not None and (not isinstance(self.api_key, str) or not self.api_key.strip()):
            raise ValueError("api_key must be a non-empty string when provided")
        if not isinstance(self.model, str) or not self.model or any(char not in MODEL_NAME_CHARSET for char in self.model):
            raise ValueError("model contains unsupported characters")
        if (
            not isinstance(self.timeout_seconds, (int, float))
            or isinstance(self.timeout_seconds, bool)
            or self.timeout_seconds <= 0
        ):
            raise ValueError("timeout_seconds must be positive")
        if not isinstance(self.max_retries, int) or isinstance(self.max_retries, bool) or self.max_retries < 0:
            raise ValueError("max_retries must be non-negative")
        if (
            not isinstance(self.retry_delay_seconds, (int, float))
            or isinstance(self.retry_delay_seconds, bool)
            or self.retry_delay_seconds < 0
        ):
            raise ValueError("retry_delay_seconds must be non-negative")
        if (
            not isinstance(self.max_tokens_default, int)
            or isinstance(self.max_tokens_default, bool)
            or self.max_tokens_default <= 0
        ):
            raise ValueError("max_tokens_default must be a positive integer")

    @classmethod
    def from_plugin_config(cls, config: PluginConfig) -> "ClaudeSettings":
        # Timeout and retry bounds are shared with the Gemini keys; they describe
        # the analyst's patience, not the provider.
        return cls(
            api_key=config.claude_api_key,
            model=config.claude_model,
            timeout_seconds=config.gemini_timeout_seconds,
            max_retries=config.gemini_max_retries,
            max_tokens_default=config.max_output_tokens,
        )


def _safe_error_type(body: Optional[Mapping[str, object]]) -> Optional[str]:
    """Extract ``error.type`` from an Anthropic error body, or ``None``; never the message."""
    if not isinstance(body, dict) or body.get("type") != "error":
        return None
    error = body.get("error")
    if not isinstance(error, dict):
        return None
    error_type = error.get("type")
    if not isinstance(error_type, str) or not error_type:
        return None
    cleaned = "".join(char for char in error_type[:_ERROR_TYPE_MAX_CHARS] if char in _ERROR_TYPE_CHARSET)
    return cleaned or None


def _describe_http_error(exc: HTTPError) -> Optional[str]:
    return _safe_error_type(read_error_body_json(exc))


class ClaudeProvider(LLMProvider):
    """Single-turn Claude Messages REST provider; it performs no work until called."""

    def __init__(
        self,
        settings: ClaudeSettings,
        opener: Callable[..., object] = urlopen,
        sleeper: Callable[[float], None] = time.sleep,
    ) -> None:
        self._settings = settings
        self._client = JsonHttpClient(
            provider_name="Claude",
            request_error=ClaudeRequestError,
            response_error=ClaudeResponseError,
            timeout_seconds=settings.timeout_seconds,
            max_retries=settings.max_retries,
            retry_delay_seconds=settings.retry_delay_seconds,
            retryable_status_codes=RETRYABLE_STATUS_CODES,
            opener=opener,
            sleeper=sleeper,
            describe_http_error=_describe_http_error,
        )

    def generate(self, request: LLMRequest) -> LLMResponse:
        json_mode = request.response_mime_type == "application/json"
        messages = [{"role": "user", "content": request.prompt}]
        system_text = request.system_instruction
        if json_mode:
            system_text = (system_text + "\n\n" + JSON_MODE_INSTRUCTION) if system_text else JSON_MODE_INSTRUCTION
            messages.append({"role": "assistant", "content": JSON_PREFILL})
        payload = {
            "model": self._settings.model,
            "max_tokens": request.max_output_tokens or self._settings.max_tokens_default,
            "messages": messages,
        }
        if system_text:
            payload["system"] = system_text
        if request.temperature is not None:
            payload["temperature"] = request.temperature
        response = self._request_json("POST", "/messages", payload)
        return self._parse_response(response, prefill=JSON_PREFILL if json_mode else "")

    def health_check(self) -> ProviderHealth:
        try:
            self._request_json("GET", "/models?limit=1", None)
        except LLMProviderError as exc:
            return ProviderHealth(available=False, model=self._settings.model, detail=str(exc))
        return ProviderHealth(available=True, model=self._settings.model)

    def list_models(self) -> Tuple[str, ...]:
        """Model ids from ``GET /v1/models`` (``data[].id``), bounded; one page, no pagination."""
        response = self._request_json("GET", "/models?limit={0}".format(MAX_LISTED_MODELS), None)
        data = response.get("data")
        if not isinstance(data, list):
            raise ClaudeResponseError("Claude models response did not contain a data list")
        ids: List[str] = []
        for entry in data:
            if len(ids) >= MAX_LISTED_MODELS:
                break
            if isinstance(entry, dict):
                model_id = entry.get("id")
                if isinstance(model_id, str) and model_id:
                    ids.append(model_id)
        return tuple(ids)

    def _request_json(self, method: str, path: str, payload: Optional[Mapping[str, object]]) -> Mapping[str, object]:
        api_key = self._settings.api_key
        if not api_key:
            raise MissingApiKeyError("Claude API key is not configured")
        headers = {
            "content-type": "application/json",
            "x-api-key": api_key,
            "anthropic-version": ANTHROPIC_VERSION,
            "User-Agent": USER_AGENT,
        }
        response = self._client.request_json(method, CLAUDE_API_BASE_URL + path, headers, payload)
        if response.get("type") == "error":
            error_type = _safe_error_type(response)
            raise ClaudeRequestError(
                "Claude request failed ({0})".format(error_type) if error_type else "Claude request failed"
            )
        return response

    def _parse_response(self, response: Mapping[str, object], prefill: str) -> LLMResponse:
        content = response.get("content")
        if not isinstance(content, list):
            raise ClaudeResponseError("Claude response did not contain content blocks")
        text = "".join(
            block["text"]
            for block in content
            if isinstance(block, dict) and block.get("type") == "text" and isinstance(block.get("text"), str)
        )
        if not text:
            raise ClaudeResponseError("Claude response did not contain text")
        stop_reason = response.get("stop_reason")
        return LLMResponse(
            text=prefill + text,
            model=self._settings.model,
            finish_reason=stop_reason if isinstance(stop_reason, str) else None,
            usage=usage_from(response.get("usage"), "input_tokens", "output_tokens"),
        )

