    on_url: Optional[Callable[[str], None]] = None,
    timeout_seconds: float = SIGN_IN_TIMEOUT_SECONDS,
) -> str:
    """Run ``ant auth login`` (it opens the browser); cancel with ``cancel_sign_in()``."""
    global _sign_in_process
    if not _sign_in_lock.acquire(blocking=False):
        raise ClaudeSignInError("A Claude sign-in is already in progress; finish it in the browser or cancel it")
    try:
        ant = _require_ant(ant_path)
        kwargs = {}
        if os.name == "nt":
            kwargs["creationflags"] = _CREATE_NO_WINDOW
        try:
            process = subprocess.Popen(
                [ant, "auth", "login"] + _profile_args(profile),
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, text=True,
                env=_environment(), **kwargs,
            )
        except OSError as exc:
            raise ClaudeSignInError("The Anthropic CLI could not be started ({0})".format(type(exc).__name__)) from exc
        _sign_in_process = process
        output: List[str] = []

        def reader() -> None:
            stream = process.stdout
            if stream is None:
                return
            for line in stream:
                output.append(line)
                match = _URL_RE.search(line)
                if match and on_url is not None:
                    try:
                        on_url(match.group(0).rstrip(".,)"))
                    except Exception:
                        pass

        thread = threading.Thread(target=reader, daemon=True)
        thread.start()
        try:
            process.wait(timeout=max(10.0, float(timeout_seconds)))
        except subprocess.TimeoutExpired:
            process.kill()
            raise ClaudeSignInError("Claude sign-in timed out; start it again from Settings")
        thread.join(timeout=2.0)
        if process.returncode != 0:
            if getattr(process, "_cancelled", False):
                raise ClaudeSignInError("Claude sign-in cancelled")
            raise ClaudeSignInError("Claude sign-in did not complete (ant exited with code {0})".format(process.returncode))
        forget_cached_token()
        access_token(ant_path, profile)  # proves the new profile works
        return "Signed in with Claude" + (" (profile {0})".format(profile) if profile else "")
    finally:
        _sign_in_process = None
        _sign_in_lock.release()


def cancel_sign_in() -> bool:
    process = _sign_in_process
    if process is None or process.poll() is not None:
        return False
    try:
        process._cancelled = True  # type: ignore[attr-defined]
        process.terminate()
    except OSError:
        return False
    return True


def sign_in_in_progress() -> bool:
    return _sign_in_lock.locked()


def sign_out(ant_path: Optional[str] = None, profile: Optional[str] = None) -> str:
    forget_cached_token()
    ant = _require_ant(ant_path)
    result = _run([ant, "auth", "logout"] + _profile_args(profile), 30.0)
    if result.returncode != 0:
        raise ClaudeSignInError("Claude sign-out did not complete (ant exited with code {0})".format(result.returncode))
    return "Signed out of Claude" + (" (profile {0})".format(profile) if profile else "")


__all__ = [
    "ClaudeSignInError", "OAUTH_BETA", "access_token", "cancel_sign_in", "find_ant", "forget_cached_token",
    "is_signed_in", "sign_in", "sign_in_in_progress", "sign_out",
]

