def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _bounded_int(values: Mapping[str, Any], name: str, bounds: Tuple[int, int, int]) -> int:
    """Integer key within ``(default, minimum, maximum)``; a missing key yields the default."""
    default, minimum, maximum = bounds
    value = values.get(name, default)
    if not _is_int(value) or not minimum <= value <= maximum:
        raise ConfigurationError("{0} must be an integer from {1} to {2}".format(name, minimum, maximum))
    return value


def user_config_dir() -> Path:
    """Per-user directory IDA itself uses for user files (``IDAUSR`` honoured).

    Windows: ``%APPDATA%\\Hex-Rays\\IDA Pro``; elsewhere ``~/.idapro``.
    """
    idausr = os.environ.get("IDAUSR")
    if idausr:
        first = idausr.split(os.pathsep)[0].strip()
        if first:
            return Path(first)
    appdata = os.environ.get("APPDATA")
    if os.name == "nt" and appdata:
        return Path(appdata) / "Hex-Rays" / "IDA Pro"
    return Path.home() / ".idapro"


def _directory_writable(directory: Path) -> bool:
    try:
        directory.mkdir(parents=True, exist_ok=True)
        probe = directory / (".write-test-" + str(os.getpid()))
        with probe.open("w", encoding="utf-8") as handle:
            handle.write("")
        probe.unlink()
        return True
    except OSError:
        return False


def config_path_for(plugin_root: Path) -> Path:
    """The configuration file the plugin reads and the Settings dialog writes.

    A file already beside the plugin, else one in the per-user IDA directory,
    else the plugin folder when writable, else the per-user directory.
    """
    beside_plugin = Path(plugin_root) / CONFIG_FILE_NAME
    if beside_plugin.is_file():
        return beside_plugin
    per_user = user_config_dir() / CONFIG_FILE_NAME
    if per_user.is_file():
        return per_user
    if _directory_writable(Path(plugin_root)):
        return beside_plugin
    return per_user


def load_file_config(path: Optional[Path]) -> PluginConfig:
    """Load only the JSON file (no environment overrides); a missing file yields the defaults."""
    if path is None or not path.is_file():
        return PluginConfig()
    try:
        with path.open("r", encoding="utf-8") as config_file:
            raw = json.load(config_file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ConfigurationError("Could not read configuration file: {0}".format(path)) from exc
    if not isinstance(raw, dict):
        raise ConfigurationError("Configuration root must be a JSON object")
    return PluginConfig.from_mapping(raw)


def save_config(config: PluginConfig, path: Path, include_secrets: bool = False) -> Path:
    """Write ``config`` as pretty JSON, atomically, readable only by the current user where possible."""
    del include_secrets
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(config.to_mapping(), indent=2) + "\n"
    temporary = target.with_name(target.name + ".tmp")
    descriptor = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, stat.S_IRUSR | stat.S_IWUSR)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.chmod(str(temporary), stat.S_IRUSR | stat.S_IWUSR)
        except OSError:
            pass
        os.replace(str(temporary), str(target))
    except BaseException:
        try:
            os.unlink(str(temporary))
        except OSError:
            pass
        raise
    return target


def env_overrides_active() -> Dict[str, str]:
    """Environment variables currently set that override file values: ``{name: field}`` (names only)."""
    return {name: field_name for name, field_name in ENV_OVERRIDE_FIELDS.items() if os.environ.get(name) is not None}


def load_config(path: Optional[Path] = None) -> PluginConfig:
    """Load the optional JSON config file; ``IDA_AI_PROVIDER`` / ``IDA_AI_MODEL`` override it."""
    loaded = load_file_config(path)
    overrides: Dict[str, Any] = {}
    provider = os.environ.get(PROVIDER_ENV_VAR)
    if provider is not None and provider.strip():
        candidate = provider.strip().lower()
        candidate = RETIRED_PROVIDERS.get(candidate, candidate)
        if candidate not in PROVIDERS:
            raise ConfigurationError("{0} must be one of: {1}".format(PROVIDER_ENV_VAR, ", ".join(PROVIDERS)))
        overrides["provider"] = candidate
    model = os.environ.get(MODEL_ENV_VAR)
    if model is not None and model.strip():
        active = overrides.get("provider", loaded.provider)
        overrides[MODEL_FIELD_BY_PROVIDER[active]] = model.strip()
    return replace(loaded, **overrides) if overrides else loaded

