def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _bounded_int(values: Mapping[str, Any], name: str, bounds: Tuple[int, int, int]) -> int:
    """Integer key within ``(default, minimum, maximum)``; a missing key yields the default."""
    default, minimum, maximum = bounds
    value = values.get(name, default)
    if not _is_int(value) or not minimum <= value <= maximum:
        raise ConfigurationError("{0} must be an integer from {1} to {2}".format(name, minimum, maximum))
