PROVIDER_ENV_VAR = "IDA_AI_PROVIDER"
MODEL_ENV_VAR = "IDA_AI_MODEL"
DEFAULT_CLAUDE_MODEL = "claude-opus-5-5"
DEFAULT_CHATGPT_MODEL = "gpt-6.1-sol"
DEFAULT_PROVIDER = "chatgpt"
# Provider id -> (display label, unused legacy slot). ChatGPT first: it is the primary sign-in.
PROVIDERS = {
    "chatgpt": ("ChatGPT (browser sign-in)", ""),
    "claude": ("Claude (browser sign-in via Anthropic CLI)", ""),
}
# Old provider values that no longer exist (API-key providers) -> replacement.
RETIRED_PROVIDERS = {"gemini": "chatgpt", "openai": "chatgpt", "radox": "chatgpt", "freemodel": "chatgpt"}
# Kept for callers that iterate credential fields; there are none any more.
SECRET_FIELDS: Tuple[str, ...] = ()
MODEL_FIELD_BY_PROVIDER = {"claude": "claude_model", "chatgpt": "chatgpt_model"}
# Environment variable -> configuration field it overrides at load time.
ENV_OVERRIDE_FIELDS = {PROVIDER_ENV_VAR: "provider", MODEL_ENV_VAR: "active model"}
# Keys of older configuration files that are read but ignored (and not written back).
LEGACY_IGNORED_KEYS = frozenset({
    "gemini_api_key", "gemini_model", "claude_api_key", "openai_api_key", "openai_base_url", "openai_model", "openai_json_mode",
})
# Keys of older configuration files that were renamed.
LEGACY_RENAMED_KEYS = {"gemini_timeout_seconds": "request_timeout_seconds", "gemini_max_retries": "max_retries"}
MAX_TIMEOUT_SECONDS = 900.0
MAX_RETRIES = 5
MAX_OUTPUT_TOKENS_LIMIT = 128000
# Budget keys (Investigate Binary sweep and triage entropy sampling): (default, minimum, maximum).
SWEEP_MAX_FUNCTIONS_RANGE = (8, 1, 200)
SWEEP_BATCH_TOKENS_RANGE = (6000, 1000, 32000)
SWEEP_TOKEN_BUDGET_RANGE = (60000, 2000, 2_000_000)
ENTROPY_SAMPLE_BYTES_RANGE = (1 << 20, 65536, 16 << 20)


class ConfigurationError(ValueError):
    """Raised when a configuration file cannot be safely interpreted."""


@dataclass(frozen=True)
class PluginConfig:
    """Local plugin settings (no credentials: sign-in tokens live with their sign-in module)."""

    debug_logging: bool = False
    panel_title: str = "AI Assistant"
    provider: str = DEFAULT_PROVIDER
    chatgpt_model: str = DEFAULT_CHATGPT_MODEL
    claude_model: str = DEFAULT_CLAUDE_MODEL
    #: ``ant`` profile to use for Claude (empty = the CLI's active profile).
    claude_profile: str = ""
    #: Full path of ``ant`` when it is not on ``PATH``.
    ant_path: str = ""
    request_timeout_seconds: float = 120.0
    max_retries: int = 2
    max_agent_iterations: int = 10
    max_output_tokens: int = 4096
    #: Only sent to models that accept sampling parameters (current Claude/ChatGPT plan models do not).
    temperature: float = 0.2
    show_external_ai_notice: bool = True
    sweep_max_functions: int = SWEEP_MAX_FUNCTIONS_RANGE[0]
    sweep_batch_tokens: int = SWEEP_BATCH_TOKENS_RANGE[0]
    sweep_token_budget: int = SWEEP_TOKEN_BUDGET_RANGE[0]
    entropy_sample_bytes: int = ENTROPY_SAMPLE_BYTES_RANGE[0]
    sweep_early_stop: bool = True
