            provider = RETIRED_PROVIDERS[provider]
        if provider not in PROVIDERS:
            raise ConfigurationError("provider must be one of: " + ", ".join(PROVIDERS))

        def text(name: str, default: str, allow_empty: bool = False) -> str:
            value = working.get(name, default)
            if not isinstance(value, str) or (not allow_empty and not value.strip()):
                raise ConfigurationError("{0} must be a{1} string".format(name, "" if allow_empty else " non-empty"))
