            raise ConfigurationError("max_retries must be an integer from 0 to {0}".format(MAX_RETRIES))
        iterations = working.get("max_agent_iterations", 10)
        if not _is_int(iterations) or not 1 <= iterations <= 50:
            raise ConfigurationError("max_agent_iterations must be an integer from 1 to 50")
        max_tokens = working.get("max_output_tokens", 4096)
        if not _is_int(max_tokens) or not 1 <= max_tokens <= MAX_OUTPUT_TOKENS_LIMIT:
            raise ConfigurationError("max_output_tokens must be an integer from 1 to {0}".format(MAX_OUTPUT_TOKENS_LIMIT))
        temperature = working.get("temperature", 0.2)
