            max_retries=retries,
            max_agent_iterations=iterations,
            max_output_tokens=max_tokens,
            temperature=float(temperature),
            show_external_ai_notice=boolean("show_external_ai_notice", True),
            sweep_max_functions=_bounded_int(working, "sweep_max_functions", SWEEP_MAX_FUNCTIONS_RANGE),
            sweep_batch_tokens=_bounded_int(working, "sweep_batch_tokens", SWEEP_BATCH_TOKENS_RANGE),
