from __future__ import annotations

from ida_ai_malware_analyst_plugin.core.config import ConfigurationError, PluginConfig
from ida_ai_malware_analyst_plugin.llm.base import LLMProvider
from ida_ai_malware_analyst_plugin.llm.claude import ClaudeProvider, ClaudeSettings
from ida_ai_malware_analyst_plugin.llm.gemini import GeminiProvider, GeminiSettings
from ida_ai_malware_analyst_plugin.llm.openai_compat import OpenAICompatProvider, OpenAICompatSettings
from ida_ai_malware_analyst_plugin.llm.chatgpt import ChatGPTProvider


def build_provider(config: PluginConfig) -> LLMProvider:
    """Return the provider selected by ``config.provider``; no network activity happens here."""
    if config.provider == "gemini":
        return GeminiProvider(GeminiSettings.from_plugin_config(config))
    if config.provider == "claude":
        return ClaudeProvider(ClaudeSettings.from_plugin_config(config))
    if config.provider == "openai":
        return OpenAICompatProvider(OpenAICompatSettings.from_plugin_config(config))
    if config.provider == "chatgpt":
        return ChatGPTProvider(config.chatgpt_model, timeout_seconds=config.gemini_timeout_seconds)
    raise ConfigurationError("Unsupported provider: {0}".format(config.provider))

