    """Revoke a refresh token at OpenAI's verified revocation endpoint; ``True`` when confirmed."""
    discovery = _http_json(ISSUER + "/.well-known/openid-configuration", timeout=timeout)
    revoke_url = discovery.get("revocation_endpoint")
    parsed_revoke = urlsplit(revoke_url) if isinstance(revoke_url, str) else None
    if parsed_revoke is None or parsed_revoke.scheme != "https" or parsed_revoke.hostname != "auth.openai.com":
        raise ChatGPTError("ChatGPT revocation endpoint could not be verified")
    body = urllib.parse.urlencode({"token": token, "token_type_hint": "refresh_token", "client_id": client_id}).encode("ascii")
    headers = {"Content-Type": "application/x-www-form-urlencoded", "User-Agent": "IDA-AI-Malware-Analyst"}
    confirmed = False
    for attempt in range(max(1, attempts)):
        request = urllib.request.Request(revoke_url, data=body, method="POST", headers=headers)
        try:
