# -- triage navigation ----------------------------------------------

def _fill_jump_targets(self, report: Any) -> None:
    if self._triage_list is None:
        return
    if isinstance(report, BinaryTriageOutcome):
        rows = [(format_jump_label(index, address, name, role), address) for index, (address, name, role) in enumerate(binary_triage_jump_targets(report), start=1)]
    elif isinstance(report, TriageReport):
        rows = [(format_jump_target(address, name), address) for address, name in triage_jump_targets(report)]
    else:
        return
    self._triage_list.clear()
    for label, address in rows:
        item = QtWidgets.QListWidgetItem(label)
        item.setData(QtCore.Qt.UserRole, address)
        self._triage_list.addItem(item)
    if self._sweep_button is not None:
        self._sweep_button.setText(self._sweep_caption())

def _jump_to_item(self, item) -> None:
    address = item.data(QtCore.Qt.UserRole)
    if isinstance(address, int) and not isinstance(address, bool):
        self._actions.jump_to(address)

# -- proposed changes ---------------------------------------------

def refresh_changes(self) -> None:
    if self._change_list is not None:
        selected = self._selected_change_id()
        self._change_list.clear()
        include_applied = bool(self._show_applied is not None and self._show_applied.isChecked())
        try:
            changes = self._changes.list_changes(include_applied=include_applied)
        except TypeError:  # older controllers: no filter argument
            changes = self._changes.list_changes()
        if not changes:
            placeholder = QtWidgets.QListWidgetItem("No changes waiting for approval.")
            placeholder.setFlags(QtCore.Qt.NoItemFlags)
            self._change_list.addItem(placeholder)
        for change in changes:
            item = QtWidgets.QListWidgetItem(format_change_row(change))
            item.setData(QtCore.Qt.UserRole, change.change_id)
            item.setData(QtCore.Qt.UserRole + 1, str(getattr(change.status, "value", change.status)))
            self._change_list.addItem(item)
            if change.change_id == selected:
                self._change_list.setCurrentItem(item)
    if self._audit is not None:
        self._audit.setPlainText("\n".join(format_audit_entry(entry) for entry in self._changes.audit_entries()))

