"""Deterministic Markdown report generation from analysis history (AGENTS.md section 41).

The report is assembled locally from recorded history, pending proposals and
the audit trail; no model call is required. An optional AI executive summary
can be requested separately and is inserted verbatim under its own heading.
No IDA access happens here; the integrator supplies the binary name and paths.
"""

from __future__ import annotations

import json
import hashlib
import re
import struct
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

from ida_ai_malware_analyst_plugin import __version__
from ida_ai_malware_analyst_plugin.analysis.binary_triage import (
    analysis_path_to_list,
    call_flows_to_list,
    verdict_to_dict,
)
from ida_ai_malware_analyst_plugin.analysis.function import FunctionAnalysis, load_prompt
from ida_ai_malware_analyst_plugin.analysis.investigation import (
    STAGE_TITLES,
    InvestigationResult,
    investigation_from_payload,
    merge_investigations,
)
from ida_ai_malware_analyst_plugin.analysis.iocs import INDICATOR_KINDS, KIND_TITLES
from ida_ai_malware_analyst_plugin.core.budget import format_tokens
from ida_ai_malware_analyst_plugin.core.history import HistoryEntry
from ida_ai_malware_analyst_plugin.core.parsing import strip_json_fence
from ida_ai_malware_analyst_plugin.llm.base import LLMRequest

MAX_REPORT_BYTES = 512 * 1024
MAX_SUMMARY_REQUEST_BYTES = 16 * 1024
# Bounds on the model-written executive summary before it enters the report.
MAX_SUMMARY_CHARS = 8000
MAX_SUMMARY_ITEMS = 50
REPORT_TRUNCATION_NOTE = "\n\n> Report truncated at the 512 KiB limit.\n"
APPLIED_STATUSES = ("APPLIED", "APPLIED_UNVERIFIED", "ROLLED_BACK")

METHODOLOGY_NOTE = (
    "This report was produced with AI assistance inside IDA Pro. IDA is the ground truth for every "
    "address, name and instruction quoted here; model output was validated against collected context "
    "before being recorded. All IDB changes listed as applied were explicitly approved by the analyst "
    "and are audited and reversible. Findings are labelled Observed, Inferred or Hypothesis; nothing in "
    "this document should be treated as a confirmed IOC without independent verification."
)


class ReportResponseError(ValueError):
    """The model summary cannot be safely rendered into the report."""


@dataclass(frozen=True)
class ReportInputs:
    binary_name: str
    generated_at: float
    history: Tuple[HistoryEntry, ...]
    pending_changes: Tuple[dict, ...]
    audit_entries: Tuple[dict, ...]
    triage_text: Optional[str] = None
    analyst_notes: str = ""
    sample_path: Optional[str] = None


# ---------------------------------------------------------------------------
# Payload conventions shared with the integrator
# ---------------------------------------------------------------------------


def _hex(address: Any) -> str:
    if isinstance(address, bool):
        return str(address)
    if isinstance(address, int):
        return "0x{0:X}".format(address)
    if isinstance(address, str):
        text = address.strip()
        if re.match(r"^0[xX][0-9A-Fa-f]+$", text):
            return "0x{0:X}".format(int(text, 16))
        if text.isdigit():
            return "0x{0:X}".format(int(text))
    return str(address) if address is not None else "-"


def function_analysis_payload(analysis: FunctionAnalysis) -> dict:
    return {
        "summary": analysis.summary,
        "observed_behavior": list(analysis.observed_behavior),
        "inferences": list(analysis.inferences),
        "hypotheses": list(analysis.hypotheses),
        "important_apis": list(analysis.important_apis),
        "important_strings": list(analysis.important_strings),
        "related_functions": list(analysis.related_functions),
        "evidence": list(analysis.evidence),
        "behavior_confidence": float(analysis.behavior_confidence),
        "confidence_label": analysis.confidence_label,
        "uncertainties": list(analysis.uncertainties),
        "suggested_name": analysis.suggested_name,
    }


def capability_payload(report: Any) -> dict:
    findings = []
    for item in getattr(report, "findings", ()):
        findings.append({
            "category": item.category,
            "capability": item.capability,
            "description": item.description,
            "evidence": list(item.evidence),
            "apis": list(item.apis),
            "strings": list(item.strings),
            "confidence": float(item.confidence),
            "confidence_label": item.confidence_label,
            "basis": item.basis,
            "mitre_technique": item.mitre_technique,
        })
    return {
        "summary": getattr(report, "summary", ""),
        "findings": findings,
        "local_signals": [
            {"category": s.category, "label": s.label, "strength": s.strength, "mitre_technique": s.mitre_technique}
            for s in getattr(report, "local_signals", ())
        ],
        "uncertainties": list(getattr(report, "uncertainties", ())),
    }


def obfuscation_payload(report: Any) -> dict:
    return {
        "summary": getattr(report, "summary", ""),
        "findings": [
            {
                "kind": f.kind,
                "technique": f.technique,
                "description": f.description,
                "evidence": list(f.evidence),
                "confidence": float(f.confidence),
                "basis": f.basis,
                "suggested_helper": f.suggested_helper,
            }
            for f in getattr(report, "findings", ())
        ],
        "local_signals": [
            {"kind": s.kind, "description": s.description, "addresses": [_hex(a) for a in s.addresses],
             "confidence": float(s.confidence)}
            for s in getattr(report, "local_signals", ())
        ],
        "decoded_artifacts": [
            {
                "helper": a.helper,
                "status": a.status,
                "detail": a.detail,
                "hex_preview": a.hex_preview,
                "printable_preview": a.printable_preview,
            }
            for a in getattr(report, "decoded_artifacts", ())
        ],
        "uncertainties": list(getattr(report, "uncertainties", ())),
    }


def naming_payload(result: Any) -> dict:
    def _suggestion(s: Any) -> dict:
        return {
            "kind": s.kind,
            "address": _hex(s.address),
            "current_name": s.current_name,
            "suggested_name": s.suggested_name,
            "reason": s.reason,
            "confidence": float(s.confidence),
        }

    return {
        "function": [_suggestion(s) for s in getattr(result, "function", ())],
        "variables": [_suggestion(s) for s in getattr(result, "variables", ())],
        "globals": [_suggestion(s) for s in getattr(result, "globals", ())],
        "uncertainties": list(getattr(result, "uncertainties", ())),
    }


def triage_payload(report: Any, top_n: int = 10) -> dict:
    """History payload for a ``TriageReport`` or a ``BinaryTriageOutcome`` (adds verdict, packing, flows, path)."""
    outcome = report if hasattr(report, "verdict") and hasattr(report, "report") else None
    if outcome is not None:
        report = outcome.report
    payload = {
        "architecture": getattr(report, "architecture_label", None) or getattr(report, "architecture", None),
        "file_type": getattr(report, "file_type", None),
        "counts": {
            "functions": getattr(report, "function_count", 0),
            "imports": getattr(report, "import_count", 0),
            "strings": getattr(report, "string_count", 0),
            "segments": getattr(report, "segment_count", 0),
        },
        "top_functions": [
            {"address": _hex(f.address), "name": f.name, "score": f.score, "reasons": list(f.reasons)[:5]}
            for f in tuple(getattr(report, "high_interest", ()))[:top_n]
        ],
        "suspicious_import_count": len(getattr(report, "suspicious_imports", ())),
        "ai_summary": getattr(report, "ai_summary", None),
        "ai_highlights": [
            {"address": _hex(h.address), "name": h.name, "why": h.why, "priority": h.priority}
            for h in getattr(report, "ai_highlights", ())
        ],
        "recommended_investigation": list(getattr(report, "recommended_investigation", ())),
        "uncertainties": list(getattr(report, "uncertainties", ())),
    }
    if outcome is not None:
        payload["verdict"] = verdict_to_dict(outcome.verdict)
        payload["packing"] = outcome.packing.to_dict() if outcome.packing is not None else None
        payload["analysis_path"] = analysis_path_to_list(outcome.path)
        payload["call_flows"] = call_flows_to_list(outcome.flows)
    return payload


def investigation_payload(trace: Sequence[str], analysis: Any) -> dict:
    payload: Dict[str, Any] = {"trace": [str(step) for step in trace], "steps": len(trace)}
    if isinstance(analysis, FunctionAnalysis):
        payload["analysis"] = function_analysis_payload(analysis)
    elif isinstance(analysis, dict):
        payload["analysis"] = analysis
    elif analysis is not None:
        payload["analysis"] = {"summary": str(analysis)}
    return payload


# ---------------------------------------------------------------------------
# Markdown helpers
# ---------------------------------------------------------------------------

_LEADING_MARKUP = re.compile(r"^([#>\-+*]|\d+\.)")


def escape_md(text: Any) -> str:
    """Neutralise Markdown structure in sample-derived strings."""
    value = "" if text is None else str(text)
    value = value.replace("\r", " ").replace("\n", " ")
    value = value.replace("\\", "\\\\").replace("`", "\\`").replace("|", "\\|")
    value = value.replace("[", "\\[").replace("]", "\\]").replace("<", "&lt;")
    stripped = value.lstrip()
    if stripped and _LEADING_MARKUP.match(stripped):
        value = "\\" + stripped
    return value


def _cell(text: Any) -> str:
    return escape_md(text).strip() or "-"


def _table(headers: Sequence[str], rows: Iterable[Sequence[Any]]) -> List[str]:
    lines = ["| " + " | ".join(headers) + " |", "|" + "|".join(" --- " for _ in headers) + "|"]
    for row in rows:
        lines.append("| " + " | ".join(_cell(item) for item in row) + " |")
    return lines


def _bullets(items: Iterable[Any], empty: str = "_None recorded._") -> List[str]:
    out = ["- " + escape_md(item) for item in items if str(item).strip()]
    return out or [empty]


def _iso(timestamp: float) -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(timestamp))


def _strings(value: Any) -> List[str]:
    if isinstance(value, (list, tuple)):
        return [str(item) for item in value if isinstance(item, str)]
    return []


def _function_label(address: Optional[int], name: Optional[str]) -> str:
    parts = []
    if address is not None:
        parts.append(_hex(address))
    if name:
        parts.append(escape_md(name))
    return " ".join(parts) or "(unknown function)"


def _latest_per_function(history: Sequence[HistoryEntry], kind: str) -> List[HistoryEntry]:
    latest: Dict[Tuple[Optional[int], Optional[str]], HistoryEntry] = {}
    for entry in history:
        if entry.kind == kind:
            latest[(entry.function_address, entry.function_name)] = entry
    return sorted(latest.values(), key=lambda e: (e.function_address is None, e.function_address or 0))


def _analysis_from_entry(entry: HistoryEntry) -> Optional[dict]:
    if entry.kind == "function_analysis":
        return entry.payload
    if entry.kind == "investigation" and isinstance(entry.payload.get("analysis"), dict):
        return entry.payload["analysis"]
    return None


def _latest_analyses(history: Sequence[HistoryEntry]) -> List[Tuple[HistoryEntry, dict]]:
    latest: Dict[Tuple[Optional[int], Optional[str]], Tuple[HistoryEntry, dict]] = {}
    for entry in history:
        analysis = _analysis_from_entry(entry)
        if analysis is not None:
            latest[(entry.function_address, entry.function_name)] = (entry, analysis)
    return sorted(latest.values(), key=lambda p: (p[0].function_address is None, p[0].function_address or 0))


def _change_field(change: Any, *names: str) -> Any:
    source = change if isinstance(change, Mapping) else vars(change) if hasattr(change, "__dict__") else {}
    for name in names:
        if name in source and source[name] is not None:
            value = source[name]
            return getattr(value, "value", value)
    return None


# ---------------------------------------------------------------------------
# Sections
# ---------------------------------------------------------------------------

    else:
        lines.extend(["", "**Confidence:** Not assessed", "", "**Justification:** No binary triage verdict is available in the recorded analysis."])
    lines.extend(["", "## 8. Analyst Conclusion", "", _analyst_conclusion(verdict, findings, capabilities), ""])
    return _cap("\n".join(lines))


def _latest_triage(history: Sequence[HistoryEntry]) -> dict:
    return next((entry.payload for entry in reversed(history) if entry.kind == "triage"), {})


def _sample_metadata(path: Optional[str], triage: Mapping[str, Any]) -> dict:
    file_type = triage.get("file_type") or "Unknown"
    architecture = triage.get("architecture") or "Unknown"
    meta = {"File type": str(file_type), "Architecture": str(architecture), "File size": "Unavailable",
            "Entry point": "Unavailable", "SHA256": "Unavailable", "Digital signature": "Unknown"}
    if not path:
        return meta
    try:
        target = Path(path)
        size = target.stat().st_size
        meta["File size"] = "{0} bytes".format(size)
        digest = hashlib.sha256()
        with target.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
        meta["SHA256"] = digest.hexdigest()
        with target.open("rb") as handle:
            header = handle.read(4096)
        pe = _pe_metadata(header)
        if pe:
            meta["Entry point"] = "RVA {0} / VA {1}".format(_hex(pe["rva"]), _hex(pe["image_base"] + pe["rva"]))
            meta["Digital signature"] = "Signed (certificate present; validity not verified)" if pe["signed"] else "Unsigned"
            if str(file_type).lower() == "unknown":
                meta["File type"] = "PE32+ EXE" if pe["is_64"] else "PE32 EXE"
            if str(architecture).lower() == "unknown":
                meta["Architecture"] = "x64" if pe["is_64"] else "x86"
        return meta
    except (OSError, ValueError, struct.error):
        return meta


def _pe_metadata(data: bytes) -> Optional[dict]:
    if len(data) < 64 or data[:2] != b"MZ":
        return None
    pe_offset = struct.unpack_from("<I", data, 0x3C)[0]
    if pe_offset + 24 > len(data) or data[pe_offset:pe_offset + 4] != b"PE\0\0":
        return None
    optional = pe_offset + 24
    magic = struct.unpack_from("<H", data, optional)[0]
    is_64 = magic == 0x20B
