"""Remove names from top-level ``from X import (...)`` statements that are not used in the file.

Only touches ImportFrom nodes; keeps ``__future__``; keeps names listed in ``__all__``.
"""
import ast
import os
import re
import sys

root = sys.argv[1]
changed = []
for d, _, fs in os.walk(root):
    for f in fs:
        if not f.endswith(".py"):
            continue
        path = os.path.join(d, f)
        src = open(path, encoding="utf-8").read()
        tree = ast.parse(src)
        exported = set()
        for node in tree.body:
            if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "__all__" for t in node.targets):
                try:
                    exported = set(ast.literal_eval(node.value))
                except Exception:
                    pass
        lines = src.splitlines(keepends=True)
        edits = []
        for node in tree.body:
            if not isinstance(node, ast.ImportFrom) or node.module == "__future__":
                continue
            seg = "".join(lines[node.lineno - 1:node.end_lineno])
            rest = src.replace(seg, "", 1)
            keep, drop = [], []
            for alias in node.names:
                name = alias.asname or alias.name
                if name in exported or re.search(r"\b%s\b" % re.escape(name), rest):
                    keep.append(alias)
                else:
                    drop.append(name)
            if not drop:
                continue
            if keep:
                parts = [a.name + (" as " + a.asname if a.asname else "") for a in keep]
                one = "from {0} import {1}\n".format("." * node.level + (node.module or ""), ", ".join(parts))
                if len(one) > 110:
                    one = "from {0} import (\n{1})\n".format("." * node.level + (node.module or ""),
                                                            "".join("    {0},\n".format(p) for p in parts))
                new = one
            else:
                new = ""
            edits.append((node.lineno, node.end_lineno, new, drop))
        if not edits:
            continue
        for start, end, new, drop in sorted(edits, reverse=True):
            lines[start - 1:end] = [new] if new else []
        out = "".join(lines)
        ast.parse(out)
        open(path, "w", encoding="utf-8", newline="\n").write(out)
        changed.append((os.path.relpath(path, root), [n for e in edits for n in e[3]]))
for p, names in changed:
    print(p, names)

