"""Build the release zip that an analyst unpacks into IDA's ``plugins`` directory.

    python scripts/build_release.py              # checks + tests + zip into dist/
    python scripts/build_release.py --no-tests   # skip the offline test suites

Release gates (the build stops on the first failure):
  1. every module compiles;
  2. the offline test suites pass (tests/run_tests.py);
  3. no credentials, tokens, local configuration or user-specific paths are shipped.

Only the loader, the package, prompts, the example configuration, VERSION and the
docs are packaged; tests, caches, logs, reports and local configuration never are.
"""

from __future__ import annotations

import argparse
import compileall
import os
import re
import subprocess
import sys
import zipfile
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
PLUGIN_ROOT = REPO / "ida_ai_malware_analyst"
PACKAGE = PLUGIN_ROOT / "ida_ai_malware_analyst_plugin"
DIST = REPO / "dist"

TOP_LEVEL_FILES = ("ida_ai_malware_analyst.py", "README-INSTALL.txt")
DOC_GLOBS = ("CHANGELOG-*.md", "IDA-AI-Malware-Analyst-Complete-Guide-*.md")
PLUGIN_FILES = ("VERSION", "ida_ai_malware_analyst.example.json")
EXCLUDED_DIRS = {"__pycache__", ".git", ".idea", ".vscode", "tests", "dist", "logs", "reports"}
EXCLUDED_SUFFIXES = {".pyc", ".pyo", ".log", ".db", ".sqlite", ".tmp", ".bak"}

# Things that must never ship: secrets, tokens and machine-specific paths.
SECRET_PATTERNS = (
    (re.compile(r"sk-(?:ant-)?[A-Za-z0-9_-]{20,}"), "API key"),
    (re.compile(r"eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\."), "JWT / access token"),
    (re.compile(r"\"(?:access|refresh|id)_token\"\s*:\s*\"[^\"]{16,}\""), "stored OAuth token"),
    (re.compile(r"[A-Za-z]:\\\\?Users\\\\?[A-Za-z0-9._-]+\\\\?(?:Desktop|Documents|AppData)", re.I), "user-specific path"),
    (re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.(?:com|net|org|io)\b"), "e-mail address"),
)
# Literal e-mail-like strings that are part of the product (none today); extend deliberately.
ALLOWED_MATCHES: set = set()


def version() -> str:
    return (PLUGIN_ROOT / "VERSION").read_text(encoding="utf-8").strip()


def release_files():
    """Yield ``(source_path, archive_name)`` for everything that ships."""
    for name in TOP_LEVEL_FILES:
        yield REPO / name, name
    for pattern in DOC_GLOBS:
        for path in sorted(REPO.glob(pattern)):
            yield path, path.name
    for name in PLUGIN_FILES:
        yield PLUGIN_ROOT / name, "ida_ai_malware_analyst/" + name
    for folder in (PACKAGE, PLUGIN_ROOT / "prompts"):
        for dirpath, dirnames, filenames in os.walk(folder):
            dirnames[:] = sorted(d for d in dirnames if d not in EXCLUDED_DIRS)
            for filename in sorted(filenames):
                path = Path(dirpath) / filename
                if path.suffix.lower() in EXCLUDED_SUFFIXES:
                    continue
                if path.suffix.lower() == ".json" and not path.name.endswith(".example.json"):
                    continue  # local configuration / credentials never ship
                yield path, "ida_ai_malware_analyst/" + path.relative_to(PLUGIN_ROOT).as_posix()


def check_compiles() -> None:
    if not compileall.compile_dir(str(PACKAGE), quiet=1, force=True, legacy=False):
        raise SystemExit("compile check failed")
    compile((REPO / "ida_ai_malware_analyst.py").read_text(encoding="utf-8"), "loader", "exec")
    print("[ok] all modules compile")


def run_tests() -> None:
    runner = REPO / "tests" / "run_tests.py"
    if not runner.is_file():
        raise SystemExit("tests/run_tests.py is missing")
    if subprocess.call([sys.executable, "-B", str(runner)], cwd=str(REPO)) != 0:
        raise SystemExit("offline tests failed")
    print("[ok] offline tests pass")


def check_contents(files) -> None:
    problems = []
    for path, arcname in files:
        if not path.is_file():
            problems.append("{0}: missing".format(arcname))
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        for pattern, label in SECRET_PATTERNS:
            for match in pattern.finditer(text):
                if match.group(0) in ALLOWED_MATCHES:
                    continue
                line = text.count("\n", 0, match.start()) + 1
                problems.append("{0}:{1}: {2}".format(arcname, line, label))
    if problems:
        raise SystemExit("release content check failed:\n  " + "\n  ".join(problems))
    print("[ok] no secrets, tokens, local config or user paths in {0} files".format(len(files)))


def build(files) -> Path:
    DIST.mkdir(exist_ok=True)
    target = DIST / "ida_ai_malware_analyst-{0}.zip".format(version())
    if target.exists():
        target.unlink()
    with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path, arcname in files:
            archive.write(path, arcname)
    print("[ok] wrote {0} ({1} files, {2:,} bytes)".format(target, len(files), target.stat().st_size))
    return target


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--no-tests", action="store_true", help="skip the offline test suites")
    args = parser.parse_args(argv)
    files = list(release_files())
    check_compiles()
    if not args.no_tests:
        run_tests()
    check_contents(files)
    build(files)
    for cache in PACKAGE.rglob("__pycache__"):  # compileall leaves caches behind; keep the tree clean
        for item in cache.iterdir():
            item.unlink()
        cache.rmdir()
    return 0


if __name__ == "__main__":
    sys.exit(main())

