import compileall
import os
import re
import subprocess
import sys
import zipfile
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
PLUGIN_ROOT = REPO / "ida_ai_malware_analyst"
PACKAGE = PLUGIN_ROOT / "ida_ai_malware_analyst_plugin"
DIST = REPO / "dist"

TOP_LEVEL_FILES = ("ida_ai_malware_analyst.py", "README-INSTALL.txt")
DOC_GLOBS = ("CHANGELOG-*.md", "IDA-AI-Malware-Analyst-Complete-Guide-*.md")
PLUGIN_FILES = ("VERSION", "ida_ai_malware_analyst.example.json")
EXCLUDED_DIRS = {"__pycache__", ".git", ".idea", ".vscode", "tests", "dist", "logs", "reports"}
EXCLUDED_SUFFIXES = {".pyc", ".pyo", ".log", ".db", ".sqlite", ".tmp", ".bak"}

# Things that must never ship: secrets, tokens and machine-specific paths.
SECRET_PATTERNS = (
    (re.compile(r"sk-(?:ant-)?[A-Za-z0-9_-]{20,}"), "API key"),
    (re.compile(r"eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\."), "JWT / access token"),
    (re.compile(r"\"(?:access|refresh|id)_token\"\s*:\s*\"[^\"]{16,}\""), "stored OAuth token"),
    (re.compile(r"[A-Za-z]:\\\\?Users\\\\?[A-Za-z0-9._-]+\\\\?(?:Desktop|Documents|AppData)", re.I), "user-specific path"),
    (re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.(?:com|net|org|io)\b"), "e-mail address"),
)
# Literal e-mail-like strings that are part of the product (none today); extend deliberately.
ALLOWED_MATCHES: set = set()


def version() -> str:
    return (PLUGIN_ROOT / "VERSION").read_text(encoding="utf-8").strip()


def release_files():
    """Yield ``(source_path, archive_name)`` for everything that ships."""
    for name in TOP_LEVEL_FILES:
        yield REPO / name, name
    for pattern in DOC_GLOBS:
        for path in sorted(REPO.glob(pattern)):
