    for name in PLUGIN_FILES:
        yield PLUGIN_ROOT / name, "ida_ai_malware_analyst/" + name
    for folder in (PACKAGE, PLUGIN_ROOT / "prompts"):
        for dirpath, dirnames, filenames in os.walk(folder):
            dirnames[:] = sorted(d for d in dirnames if d not in EXCLUDED_DIRS)
            for filename in sorted(filenames):
                path = Path(dirpath) / filename
                if path.suffix.lower() in EXCLUDED_SUFFIXES:
                    continue
                if path.suffix.lower() == ".json" and not path.name.endswith(".example.json"):
                    continue  # local configuration / credentials never ship
                yield path, "ida_ai_malware_analyst/" + path.relative_to(PLUGIN_ROOT).as_posix()


