    if not compileall.compile_dir(str(PACKAGE), quiet=1, force=True, legacy=False):
        raise SystemExit("compile check failed")
    compile((REPO / "ida_ai_malware_analyst.py").read_text(encoding="utf-8"), "loader", "exec")
    print("[ok] all modules compile")


